INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('e2f98da5-9c32-4ace-9e6d-75a70a420bdf', 'Acerto Crítico Aprimorado', 'Escolha uma arma. Você sabe desferir golpes mortais com a arma escolhida.', 'Escolha uma arma. Você sabe desferir golpes mortais com a arma escolhida.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Foco em Arma com a arma escolhida, bônus base de ataque +8.', 'sua margem de ameaça com a arma escolhida é dobrada. Este efeito não se acumula com qualquer outro que dobre a margem de ameaça, e é sempre o primeiro a ser aplicado.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('963b3e81-71a8-43c0-ad68-bca40d3a901e', 'Acuidade com Arma', 'Você é especialmente ágil com armas leves, que usam mais agilidade do que força bruta.', 'Você é especialmente ágil com armas leves, que usam mais agilidade do que força bruta.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13.', 'quando usa armas de corpo-a-corpo leves, você pode usar seu modificador de Destreza em vez de Força em jogadas de ataque. Se estiver usando este talento e um escudo, aplique a penalidade de armadura do escudo em jogadas de ataque.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('bc2e6558-9c24-488c-8d7d-312425684600', 'Agarrar Aprimorado', 'Você consegue agarrar melhor seus oponentes.', 'Você consegue agarrar melhor seus oponentes.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 13, Ataque Desarmado Aprimorado.', 'você recebe +4 em jogadas de ataque para agarrar.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('887ff17b-6b0b-490f-bd5e-43068ceba3aa', 'Apanhar Objetos', 'Você pode apanhar flechas, adagas e outras armas arremessadas ou disparadas contra você.', 'Você pode apanhar flechas, adagas e outras armas arremessadas ou disparadas contra você.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 15, Ataque Desarmado Aprimorado, Desviar Objetos.', 'quando usa o talento Desviar Objetos, você pode apanhar a arma ao invés de apenas desviá-la. Armas de arremesso podem ser atiradas de volta ao oponente como uma reação.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('062486e6-2322-44d3-94fb-e61ec638dbba', 'Aparar', 'Você pode usar sua arma para bloquear ataques.', 'Você pode usar sua arma para bloquear ataques.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 15, Acuidade com Arma, Especialização em Combate, bônus base de ataque +6.', 'uma vez por rodada, você pode tentar aparar um ataque que iria atingi-lo. Faça uma jogada de ataque. Se o resultado da sua jogada for maior que a do oponente, você evita o ataque. Você só pode usar este talento se estiver usando uma arma afetada pelo talento Acuidade com Arma.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('9e4c212b-5869-4acf-a790-97696d09d92f', 'Aparência Inofensiva', 'Por algum motivo — ser uma mulher, parecer fraco, ser de tamanho Pequeno... — você não parece perigoso. Isso faz com que seus inimigos hesitem antes de atacá-lo.', 'Por algum motivo — ser uma mulher, parecer fraco, ser de tamanho Pequeno... — você não parece perigoso. Isso faz com que seus inimigos hesitem antes de atacá-lo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Car 13.', 'a primeira criatura inteligente (Int 3 ou mais) que atacar você em um combate deve fazer um teste de Intuição (CD 10 + metade do seu nível + seu modificador de Carisma). Se falhar, perderá sua ação. Este talento só funciona uma vez por combate; isto é, independente da criatura falhar ou não no teste, poderá atacar você normalmente nas rodadas seguintes.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('f1755caf-cb20-40a9-b71c-caf4100917a4', 'Ataque Atordoante', 'Você sabe atingir áreas vulneráveis de seus inimigos.', 'Você sabe atingir áreas vulneráveis de seus inimigos.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Sab 13, Ataque Desarmado Aprimorado.', 'declare que está usando este talento antes de fazer um ataque desarmado. Se você acertar o ataque, além de sofrer o dano normal, a vítima deve fazer um teste de Fortitude (CD 10 + metade do seu nível + modificador de Sabedoria). Se falhar, fica atordoada por uma rodada. Você pode usar este talento um número de vezes por dia igual a 1 + seu modificador de Sabedoria. Criaturas imunes a acertos críticos não podem ser atordoadas.', '', 'você pode escolher este talento diversas vezes. Cada vez que é escolhido além da primeira, você recebe mais duas utilizações por dia.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('b05f5af2-8018-4ee3-86a6-5cf5193d61fc', 'Ataque com Escudo Aprimorado', 'Você sabe golpear com seu escudo sem perder sua proteção.', 'Você sabe golpear com seu escudo sem perder sua proteção.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Usar Escudo.', 'quando você ataca com o escudo, mantém seu bônus na CA.', 'um personagem que ataque com seu escudo perde o bônus que ele fornece à CA até sua próxima rodada.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('68d5f73f-3184-4688-87d8-eaa0abd13db8', 'Ataque Desarmado Aprimorado', 'Você sabe lutar sem armas.', 'Você sabe lutar sem armas.', 'Tormenta RPG', 0, 'feature', 'Combate', '', 'seus ataques desarmados causam 1d4 pontos de dano, e podem causar dano letal ou não-letal (à sua escolha).', 'sem este talento, ataques desarmados causam 1d3 pontos de dano, e podem causar apenas dano não letal.', 'este dano é para criaturas de tamanho Médio. Se você pertence a outra categoria de tamanho, consulte a Tabela 7-4: Dano de Armas por Tamanho para saber seu dano desarmado.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('9a460ff0-c218-444b-8307-a71ae4eeaa81', 'Ataque Duplo', 'Escolha uma arma. Você consegue atacar com velocidade impressionante com a arma escolhida.', 'Escolha uma arma. Você consegue atacar com velocidade impressionante com a arma escolhida.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Foco em Arma com a arma escolhida, bônus base de ataque +6.', 'quando faz um ataque com a arma escolhida, você pode fazer um ataque adicional na mesma ação padrão, mas sofre penalidade de –5 em ambas as jogadas de ataque.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('c6138f89-836c-4a8a-a57d-20f0fb759b89', 'Ataque em Movimento', 'Você faz ataques rápidos e se movimenta com agilidade.', 'Você faz ataques rápidos e se movimenta com agilidade.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Esquiva, Mobilidade, bônus base de ataque +4.', 'quando estiver atacando corpo-a-corpo, você pode se mover antes e depois do ataque, desde que a distância total percorrida não seja maior que seu deslocamento.', 'você pode se mover antes ou depois de um ataque, mas não ambos.', 'você não pode usar este talento se estiver de armadura pesada.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6b8c5dcd-b5f4-409f-a266-dd25cea31519', 'Ataque Giratório', 'Você é capaz de atacar todos os oponentes à sua volta em combate corpo-a-corpo.', 'Você é capaz de atacar todos os oponentes à sua volta em combate corpo-a-corpo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Int 13, Esquiva, Mobilidade, Ataque em Movimento, Especialização em Combate, bônus base de ataque +4.', 'você pode fazer um ataque corpo-a-corpo contra cada oponente adjacente. Usar este talento é uma ação completa.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('aae25425-76b6-4b3e-b7cf-c16e5cf3402e', 'Ataque Poderoso', 'Você pode sacrificar a precisão para desferir um golpe destruidor.', 'Você pode sacrificar a precisão para desferir um golpe destruidor.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 13.', 'declare que está usando este talento antes de fazer um ataque corpo-a-corpo. Você sofre uma penalidade de –2 na jogada de ataque, mas recebe +4 na jogada de dano.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('e8a28f68-709e-483b-a78e-21da9d7d3037', 'Ataque Preciso', 'Com lâminas leves, você sabe golpear com precisão mortal.', 'Com lâminas leves, você sabe golpear com precisão mortal.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 15, Acuidade com Arma, Especialização em Combate, bônus base de ataque +11.', 'quando usa uma arma afetada pelo talento Acuidade com Arma, você causa 1d6 pontos de dano adicional.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('f2378af5-64f3-4060-8178-f3f7b5baa629', 'Ataque Sagaz', 'Sua espada é ágil, e também atinge os lugares certos.', 'Sua espada é ágil, e também atinge os lugares certos.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Int 13, Acuidade com Arma, bônus base de ataque +4.', 'quando usa uma arma afetada pelo talento Acuidade com Arma, você soma seu modificador de Inteligência (além do modificador de Força) em jogadas de dano.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('4453da08-b196-468c-ba64-f8f6e333afba', 'Atropelar Aprimorado', 'Você não tem medo de passar por cima de seus oponentes.', 'Você não tem medo de passar por cima de seus oponentes.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 13, Ataque Poderoso.', 'quando você realiza a manobra atropelar, o alvo não pode escolher evitá-lo. Além disso, você recebe +4 em jogadas de ataque para atropelar.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('5730a8b2-b1a4-4175-b2a3-5013e05a3f7c', 'Bloqueio Ambidestro', 'Você é habilidoso em se defender usando duas armas ou uma arma dupla.', 'Você é habilidoso em se defender usando duas armas ou uma arma dupla.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 15, Combater com Duas Armas.', 'quando estiver usando duas armas ou uma arma dupla, você recebe +1 na classe de armadura.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('115ba3fa-2df9-4555-ae6a-4743df025818', 'Combater Com Duas Armas Aprimorado', 'Você é muito bem treinado em usar uma arma em cada mão.', 'Você é muito bem treinado em usar uma arma em cada mão.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 17, Combater com Duas Armas, bônus base de ataque +6.', 'usando o talento Combater com Duas Armas, sua penalidade em jogadas de ataque diminui para –2.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('2448fd5c-ccc1-4680-a3fe-6a348e0c8e3c', 'Combater Com Duas Armas Maior', 'Você é um mestre em usar uma arma em cada mão.', 'Você é um mestre em usar uma arma em cada mão.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 19, Combater Com Duas Armas, Combater Com Duas Armas Aprimorado, bônus base de ataque +11.', 'usando o talento Combater com Duas Armas, você não sofre nenhuma penalidade em jogadas de ataque.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('4ea90e08-987c-4c5f-8f1c-0bbc76c90086', 'Derrubar Aprimorado', 'Você sabe derrubar inimigos em combate corpo-a-corpo.', 'Você sabe derrubar inimigos em combate corpo-a-corpo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Int 13, Especialização em Combate.', '+4 em testes de derrubar.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('5a5f0356-793f-4f6e-b47b-868e4dc96532', 'Desarmar Aprimorado', 'Você sabe desarmar inimigos em combate corpo-a-corpo.', 'Você sabe desarmar inimigos em combate corpo-a-corpo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Int 13, Especialização em Combate.', '+4 em testes de desarmar.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('97bfd5fd-acbf-4988-ba92-124a2d12b7b6', 'Casca Grossa', 'Sua pele dura e calejada resiste a ferimentos.', 'Sua pele dura e calejada resiste a ferimentos.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Con 13.', 'você soma seu bônus de Constituição na CA. Este bônus não é cumulativo com armaduras.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('349779b1-ce20-4ef0-9605-776e93cd1dd8', 'Desviar Objetos', 'Você pode desviar flechas, adagas e outras armas arremessadas ou disparadas contra você.', 'Você pode desviar flechas, adagas e outras armas arremessadas ou disparadas contra você.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Ataque Desarmado Aprimorado.', 'você pode tentar desviar um ataque à distância que iria atingi-lo. Faça um teste de Reflexos. Se o resultado do seu teste for maior que a jogada de ataque do oponente, você evita o ataque. Você só pode usar este talento se estiver com uma mão livre. Armas muito grandes (como pedras de catapulta) ou criadas por magia não podem ser desviadas.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('76501960-05fd-4b57-b259-944b0185fa28', 'Combate Montado', 'Você sabe lutar cavalgando.', 'Você sabe lutar cavalgando.', 'Tormenta RPG', 0, 'feature', 'Combate', 'treinado em Cavalgar.', 'uma vez por rodada, você pode tentar desviar um ataque que iria atingir sua montaria. Faça um teste de Cavalgar. Se o resultado for maior que a jogada de ataque do oponente, você evita o ataque.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('104fa1f7-d2a8-441e-ba98-0e5a85c6b20b', 'Duro de Matar', 'Você resiste a ferimentos que fariam outros cair.', 'Você resiste a ferimentos que fariam outros cair.', 'Tormenta RPG', 0, 'feature', 'Combate', '', 'quando você sofre dano que poderia levá-lo a 0 ou menos pontos de vida, você pode ignorar completamente esse dano. Você pode usar este talento uma vez por dia.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('939786e5-d526-40ba-ac96-5c0a56b823f8', 'Combater com Duas Armas', 'Você é treinado em usar uma arma em cada mão.', 'Você é treinado em usar uma arma em cada mão.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 15.', 'se estiver usando uma arma de uma mão e uma arma leve, ou duas armas leves, você pode fazer dois ataques com a mesma ação padrão, um com cada uma. No entanto, você sofre penalidade de –4 em ambas as jogadas de ataque.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('a2759a24-d50e-483d-8e92-409da4618dff', 'Empunhadura Poderosa', 'Você consegue usar armas grandes. Exageradamente grandes.', 'Você consegue usar armas grandes. Exageradamente grandes.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 17.', 'ao usar armas uma categoria de tamanho acima da sua, sua penalidade cai para –2.', 'um personagem sem este talento usando uma arma uma categoria de tamanho acima da própria sofre penalidade de –4 em jogadas de ataque.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('ddc5c280-a44e-4c9f-b7c7-9dad5300862f', 'Empurrar Aprimorado', 'Você sabe como fazer seus inimigos recuarem.', 'Você sabe como fazer seus inimigos recuarem.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Força 13, Ataque Poderoso.', '+4 em jogadas de ataque para empurrar.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('4e8e9d0b-85fc-47e4-b364-58627aec383d', 'Especialização em Arma', 'Escolha uma arma. Seus golpes com a arma escolhida causam ferimentos profundos.', 'Escolha uma arma. Seus golpes com a arma escolhida causam ferimentos profundos.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Foco em Arma com a arma escolhida, guerreiro 4º nível.', 'usando a arma escolhida, você recebe +2 em jogadas de dano.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('39f50224-f76a-4136-a0ab-5554758d5f10', 'Especialização em Arma Aprimorada', 'Escolha uma arma. Seus golpes com a arma escolhida causam ferimentos terríveis.', 'Escolha uma arma. Seus golpes com a arma escolhida causam ferimentos terríveis.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Foco em Arma, Foco em Arma Aprimorado, Especialização em Arma com a arma escolhida, guerreiro 12º nível.', 'seu bônus no dano pelo talento Especialização em Arma aumenta para +4.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6ce59c60-e379-4a01-92bf-0923f63b1959', 'Especialização em Armadura', 'Escolha um tipo de armadura entre leve, média ou pesada. Você sabe usar esse tipo de armadura para absorver os golpes.', 'Escolha um tipo de armadura entre leve, média ou pesada. Você sabe usar esse tipo de armadura para absorver os golpes.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Foco em Armadura do tipo escolhido, guerreiro 8º nível.', 'quando usando uma armadura do tipo escolhido, você recebe redução de dano 2.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('2e9ee77b-2b70-40e7-b59a-5978e999c0f1', 'Especialização em Combate', 'Você é capaz de usar suas habilidades de combate tanto para atacar quanto para se defender.', 'Você é capaz de usar suas habilidades de combate tanto para atacar quanto para se defender.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Int 13.', 'declare que está usando este talento antes de fazer um ataque corpo-a-corpo. Você sofre –2 na jogada de ataque, mas recebe +4 na classe de armadura até o próximo turno.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('470a8aae-71b2-4f1e-b170-875366e09db0', 'Esquiva', 'Você é bom em esquivar-se de golpes.', 'Você é bom em esquivar-se de golpes.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13.', 'você recebe CA+1.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('7ecf16f6-e020-4188-9b14-7417cba5c11c', 'Fintar Aprimorado', 'Você sabe como distrair seus adversários em combate.', 'Você sabe como distrair seus adversários em combate.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Int 13, Especialização em Combate.', 'você pode realizar um teste de Enganação para fintar em combate usando uma ação de movimento.', 'fintar em combate exige uma ação padrão.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d3c674bf-2a96-447f-b2ff-0e237c93d087', 'Flerte Estratégico', 'Em pleno combate, você consegue seduzir ou embaraçar seus inimigos com uma manobra audaciosa (e nada educada). Por exemplo, beijando sua adversária durante a luta, colocando uma rosa em seu cabelo, us...', 'Em pleno combate, você consegue seduzir ou embaraçar seus inimigos com uma manobra audaciosa (e nada educada). Por exemplo, beijando sua adversária durante a luta, colocando uma rosa em seu cabelo, usando a espada para rasgar sua roupa e revelar partes interessantes de sua anatomia...', 'Tormenta RPG', 0, 'feature', 'Combate', 'Car 13, Fintar Aprimorado.', 'faça uma finta em combate contra um inimigo que possa se sentir fisicamente atraído por você. Se for bem-sucedido, sua vítima fica embaraçada e sofre penalidade de –2 em jogadas e testes até o fim do combate.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d0251cb2-bf8c-403c-90fa-71ba08419c31', 'Foco em Arma', 'Escolha uma arma. Você sabe lutar melhor com a arma escolhida. “Ataque desarmado” também pode ser escolhido como arma para este talento.', 'Escolha uma arma. Você sabe lutar melhor com a arma escolhida. “Ataque desarmado” também pode ser escolhido como arma para este talento.', 'Tormenta RPG', 0, 'feature', 'Combate', 'saber usar a arma escolhida, bônus base de ataque +1.', '+1 em jogadas de ataque com a arma escolhida.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('620d04d8-4465-4e67-93dc-2a7c20ce32c2', 'Foco em Arma Aprimorado', 'Escolha uma arma. Você sabe lutar ainda melhor com ela.', 'Escolha uma arma. Você sabe lutar ainda melhor com ela.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Foco em Arma com a arma escolhida, guerreiro 8º nível.', 'o bônus que você recebe pelo talento Foco em Arma aumenta para +2.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('7dd4ef8a-0f14-4f51-8467-2dfe2771368e', 'Foco em Armadura', 'Escolha um tipo de armadura entre leve, média ou pesada. Você é mais hábil em defesa e movimento com esse tipo.', 'Escolha um tipo de armadura entre leve, média ou pesada. Você é mais hábil em defesa e movimento com esse tipo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'saber usar o tipo de armadura escolhido.', 'quando usando uma armadura do tipo escolhido, você aumenta seu bônus de armadura em +1 e diminui sua penalidade de armadura em –1.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6a4791ba-051c-454f-94f0-2d4f07af4435', 'Golpe com Duas Mãos', 'Você consegue canalizar toda a sua força quando usa uma arma com as duas mãos.', 'Você consegue canalizar toda a sua força quando usa uma arma com as duas mãos.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 15, Ataque Poderoso.', 'quando usando uma arma de corpo-a-corpo com as duas mãos, você soma o dobro de seu modificador de Força às jogadas de dano. Este talento não pode ser usado com armas leves.', 'sem este talento, ao usar armas de duas mãos, você apenas soma seu modificador de Força ao dano.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d86188b1-cbcf-4dea-8f0f-d9a929f8ad64', 'Granadeiro', 'Explodir tudo é a forma mais garantida de causar dano ao inimigo. Mesmo que, às vezes, algum aliado também acabe se machucando um bocadinho...', 'Explodir tudo é a forma mais garantida de causar dano ao inimigo. Mesmo que, às vezes, algum aliado também acabe se machucando um bocadinho...', 'Tormenta RPG', 0, 'feature', 'Combate', 'treinado em Ofício (alquimia).', 'você recebe +2 em jogadas de ataque e dano com quaisquer armas que permitem um teste de Reflexos para reduzir seu efeito, como fogo alquímico e granadas.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('ab8e35fb-fd07-4abf-89b6-6a71be593802', 'Insulto Sagaz', 'Você sabe dizer barbaridades sobre seu adversário, deixando-o tão furioso que prejudica seu desempenho em combate.', 'Você sabe dizer barbaridades sobre seu adversário, deixando-o tão furioso que prejudica seu desempenho em combate.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Car 13, Fintar Aprimorado.', 'faça uma finta em combate. Se for bem-sucedido, seu oponente fica enfurecido e sofre uma penalidade de –2 na CA até o fim do combate.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('b16930b7-83ed-4c60-a8f9-cffd27e1571a', 'Investida Implacável', 'Você realiza ataques devastadores cavalgando em investida.', 'Você realiza ataques devastadores cavalgando em investida.', 'Tormenta RPG', 0, 'feature', 'Combate', 'treinado em Cavalgar, Combate Montado, Investida Montada.', 'quando está montado e faz uma investida, você causa dano dobrado com uma arma comum, ou triplicado com uma lança.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('4f85ac53-7525-49b1-a9ce-fd576370ea3d', 'Investida Montada', 'Você é mais eficiente fazendo ataques de investida quando está cavalgando.', 'Você é mais eficiente fazendo ataques de investida quando está cavalgando.', 'Tormenta RPG', 0, 'feature', 'Combate', 'treinado em Cavalgar, Combate Montado.', 'quando está montado e faz uma investida, você pode continuar se movendo depois do ataque. Você deve continuar se movendo em linha reta, e seu movimento total na rodada não pode ser superior ao dobro do deslocamento da montaria.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d2f1c3c9-72df-4c4c-b10c-2b63dfe70bcc', 'Lutar às Cegas', 'Você tem maiores chances de atingir alvos que não possa ver.', 'Você tem maiores chances de atingir alvos que não possa ver.', 'Tormenta RPG', 0, 'feature', 'Combate', '', 'sempre que você erra um ataque devido a camuflagem, pode rolar mais uma vez a chance de acertar. Além disso, você não fica desprevenido contra inimigos que não possa ver.', 'um personagem sem este talento fica desprevenido contra inimigos que não possa ver.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('3478f5b6-1bf5-46fd-9a13-603ddcede999', 'Mestre em Arma', 'Escolha uma arma. Você é um dos melhores guerreiros do mundo com a arma escolhida.', 'Escolha uma arma. Você é um dos melhores guerreiros do mundo com a arma escolhida.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Especialização em Arma, Especialização em Arma Aprimorada, Foco em Arma, Foco em Arma Aprimorado (todos com a arma escolhida), guerreiro 16º nível.', 'usando a arma escolhida, você recebe +1 em jogadas de ataque e dano, e sua margem de ameaça aumenta em 1. Além disso, uma vez por dia, você pode rolar outra vez uma jogada de ataque que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', 'este talento se acumula com quaisquer outros efeitos que aumentem a margem de ameaça de uma arma, mas é o último efeito a ser considerado. Assim, um personagem com Mestre em Arma e Acerto Crítico Aprimorado (machado de guerra) tem margem de ameaça 18-20.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('f704aed5-adf5-4e2e-bba9-6b2fd65c1cbe', 'Mira Apurada', 'Seus tiros têm precisão mortal.', 'Seus tiros têm precisão mortal.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Sab 13, Tiro Certeiro, Tiro Longo.', 'você pode gastar uma ação de movimento para mirar um alvo. Se fizer isso, recebe +1 em jogadas de ataque à distância realizadas contra ele na mesma rodada.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d9efb3e8-27f4-454c-8f0a-d4af4ff153ce', 'Mira Mortal', 'Entre os olhos. No coração. São lugares onde seus tiros costumam acertar!', 'Entre os olhos. No coração. São lugares onde seus tiros costumam acertar!', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 17, Sab 13, Mira Apurada, Tiro Certeiro, Tiro Longo, bônus base de ataque +11.', 'sua margem de ameaça com armas de projéteis aumenta em 1. Por exemplo, a margem de ameaça da pistola é 19-20; para um personagem com este talento, será 18-20.', '', 'este talento se acumula com quaisquer outros efeitos que aumentem a margem de ameaça de uma arma, mas é o último efeito a ser considerado. Assim, um personagem com Mira Mortal e Acerto Crítico Aprimorado (pistola) tem margem de ameaça 16-20.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('9e8149b2-28fc-4415-b572-07ef699ca227', 'Estender Magia', '', '', 'Tormenta RPG', 0, 'feature', 'Magia', '', '', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('19bb4db3-0b73-4cd0-9958-fd12c9783bbc', 'Mobilidade', 'Você é hábil em esquivar-se enquanto se movimenta.', 'Você é hábil em esquivar-se enquanto se movimenta.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Esquiva.', 'você recebe +2 na CA sempre que usa uma ação de movimento para deslocar-se.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('5c1ebc76-c56c-4230-bd5f-a22f93e8cc0a', 'Na Mosca', 'Sua mira é incrível, e seus disparos acertam onde dói mais.', 'Sua mira é incrível, e seus disparos acertam onde dói mais.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Tiro Certeiro, Tiro Preciso.', 'você soma seu modificador de Destreza em jogadas de dano com armas de ataque à distância.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('f2742e35-3e1e-4ef4-9829-29b05ded59e2', 'Panache', 'Você tem a (irritante) habilidade de humilhar seus oponentes em combate. Você pode trocar a espada de mão no meio da luta, arrancar os botões da camisa do oponente, derrubar seu charuto com um tiro, r...', 'Você tem a (irritante) habilidade de humilhar seus oponentes em combate. Você pode trocar a espada de mão no meio da luta, arrancar os botões da camisa do oponente, derrubar seu charuto com um tiro, riscar sua inicial nas roupas dele com a ponta da espada...', 'Tormenta RPG', 0, 'feature', 'Combate', 'Car 13, Especialização em Combate, Fintar Aprimorado.', '', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('a5e286dd-0f8e-4d9e-8dd1-a207f980f644', 'Perito em Arma', '', '', 'Tormenta RPG', 0, 'feature', 'Combate', 'Int 13, Acuidade com Arma, Foco em Arma com a arma escolhida.', '', '', '');
