INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6581dfec-ad40-488b-ade6-a0ef7a9aefd7', 'Visco Rubro', '', '', 'Tormenta RPG', 0, 'feature', 'Tormenta', '', '', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('742abdfb-40e2-47c2-87dd-2e5a48e7d642', 'Reflexos de Combate', 'Você consegue reagir rapidamente contra oponentes com a guarda baixa.', 'Você consegue reagir rapidamente contra oponentes com a guarda baixa.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13.', 'Se estiver adjacente a um oponente desprevenido, você pode fazer um ataque corpo-a-corpo contra ele como uma ação livre.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('8e10d549-f388-4560-bbbe-50c0dff25564', 'Perito em Arma', 'Escolha uma arma. Você consegue usar a arma escolhida para realizar façanhas incríveis.', 'Escolha uma arma. Você consegue usar a arma escolhida para realizar façanhas incríveis.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Des 13, Int 13, Acuidade com Arma, Foco em Arma com a arma escolhida.', 'Graças a uma extrema habilidade com a arma, que funciona como uma verdadeira extensão de seu corpo, você pode substituir um teste de qualquer perícia por uma jogada de ataque com a arma escolhida. Você pode, por exemplo, usar uma espada para destrancar uma fechadura (Ladinagem), como suporte para subir em algo (Atletismo), como apoio para uma cambalhota (Acrobacia), para fazer manobras impressionantes (Atuação) e assim por diante. Você pode usar este talento um número de vezes por dia igual a seu bônus de Carisma.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('afc0bb8d-9d3a-44a2-ae5d-1ce9582b5dbc', 'Saque Rápido', 'Você consegue sacar sua arma mais rápido que o normal.', 'Você consegue sacar sua arma mais rápido que o normal.', 'Tormenta RPG', 0, 'feature', 'Combate', '', 'Você pode sacar ou guardar uma arma como uma ação livre.', 'Sem este talento, sacar ou guardar uma arma exige uma ação de movimento.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('2d2f0ad4-8c78-4c66-b098-3fa7cdb1da8f', 'Separar Aprimorado', 'Você sabe atingir a arma do oponente, ou outro objeto que ele esteja carregando.', 'Você sabe atingir a arma do oponente, ou outro objeto que ele esteja carregando.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 13, Ataque Poderoso.', 'Você recebe +4 em jogadas de ataque para separar. Além disso, você causa dano dobrado contra objetos.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('bc3d6f2f-320a-4950-b7b5-cf55ae0811fb', 'Pisotear', 'Você sabe usar sua montaria para atropelar oponentes.', 'Você sabe usar sua montaria para atropelar oponentes.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Treinado em Cavalgar, Combate Montado.', 'Quando está montado e realiza a manobra atropelar, o alvo não pode escolher evitá-lo. Além disso, se a montaria derrubar um oponente, pode fazer um ataque contra esse oponente como uma ação livre (recebendo o bônus padrão de +4 em jogadas de ataque contra oponentes caídos).', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('0b17cbfe-77bc-46f8-961b-31f60ef0f727', 'Rapidez de Recarga', 'Escolha uma arma de disparo (como besta, funda ou pistola). Você recarrega a arma escolhida muito rapidamente.', 'Escolha uma arma de disparo (como besta, funda ou pistola). Você recarrega a arma escolhida muito rapidamente.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Saber usar a arma escolhida.', 'A ação necessária para recarregar a arma escolhida diminui em uma categoria — ação completa vira padrão, padrão vira de movimento, e de movimento vira livre. Por exemplo, recarregar um mosquete.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('0aba8eda-20f0-440a-a367-d38ac1dcac4e', 'Tiro Certeiro', 'Você é capaz de disparos precisos contra alvos próximos.', 'Você é capaz de disparos precisos contra alvos próximos.', 'Tormenta RPG', 0, 'feature', 'Combate', '', 'Você recebe +1 em jogadas de ataque e dano com armas de ataque à distância contra alvos que estejam a até 9m.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('14d38883-76a8-4de3-a922-add8ca68bc6e', 'Tiro Preciso', 'Você é capaz de mirar e disparar no momento certo.', 'Você é capaz de mirar e disparar no momento certo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Tiro Certeiro.', 'Você pode fazer ataques à distância contra oponentes envolvidos em combate corpo-a-corpo sem sofrer a penalidade de –4 na jogada de ataque.', 'Um personagem sem este talento sofre uma penalidade de –4 nos ataques à distância contra oponentes envolvidos em combate corpo-a-corpo.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('15ca20c6-3e32-4539-b268-bd044c1cb4e6', 'Tiro em Movimento', 'Você faz disparos rápidos e se movimenta com agilidade.', 'Você faz disparos rápidos e se movimenta com agilidade.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Esquiva, Mobilidade, Tiro Certeiro, bônus base de ataque +4.', 'Quando estiver atacando à distância, você pode se mover antes e depois do ataque, desde que a distância total percorrida não seja maior que seu deslocamento. Você não pode usar este talento se estiver de armadura pesada.', 'Você pode se mover antes ou depois de um ataque, mas não ambos.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('45d94b29-3a68-4df8-a343-1f1c79dba41a', 'Tiro Preciso Aprimorado', 'Sua mira é infalível.', 'Sua mira é infalível.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 19, Tiro Certeiro, Tiro Preciso, bônus base de ataque +11.', 'Seus ataques à distância ignoram cobertura e camuflagem (exceto cobertura ou camuflagem totais). Além disso, quando ataca um alvo envolvido na manobra agarrar, você acerta automaticamente o alvo que escolheu.', 'Um personagem sem este talento atacando um alvo envolvido na manobra agarrar deve determinar aleatoriamente qual alvo ele acerta.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('465ffd91-5dbb-4299-ac27-914f9a5375aa', 'Tiro Longo', 'Seus disparos de longa distância vão muito mais longe.', 'Seus disparos de longa distância vão muito mais longe.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Tiro Certeiro.', 'O incremento de distância de qualquer arma que você utiliza é dobrado.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('90561903-bdb0-4cb1-b572-b8e15a476e0e', 'Tiro Montado', 'Você é talentoso em atacar à distância enquanto cavalga.', 'Você é talentoso em atacar à distância enquanto cavalga.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Treinado em Cavalgar, Combate Montado.', 'Sua penalidade para ataques à distância quando sua montaria se movimenta é reduzida para –2.', 'Um personagem sem este talento sofre uma penalidade de –4 em jogadas de ataque à distância se, na mesma rodada, sua montaria se movimentou.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('33cb4a0c-2848-494e-8824-9be906e317af', 'Tiro Múltiplo', 'Você atira mais em menos tempo.', 'Você atira mais em menos tempo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 17, Tiro Certeiro, Tiro Rápido, bônus base de ataque +6.', 'Usando uma ação padrão e uma arma de projéteis, você pode fazer dois ataques contra um único oponente a até 9m. Ambos usam a mesma jogada (com penalidade de –4) e causam dano normalmente.', '', 'Em caso de acerto crítico, apenas o primeiro ataque causa dano multiplicado; o segundo ataque causa dano normal.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('81cf4ac2-703e-47f3-b3d6-f2439f6f32d1', 'Tiro Rápido', 'Você é muito rápido atacando à distância.', 'Você é muito rápido atacando à distância.', 'Tormenta RPG', 0, 'feature', 'Combate', 'Des 13, Tiro Certeiro.', 'Usando uma arma de ataque à distância, você pode fazer um ataque adicional. Se fizer isso, sofre uma penalidade de –2 em todas as jogadas de ataque. Usar este talento é uma ação completa.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('ce09d908-a8c6-4581-94a9-a6dd6e44fa17', 'Torcida', 'Você luta melhor quando há fãs torcendo por você.', 'Você luta melhor quando há fãs torcendo por você.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Car 13.', 'Você recebe +1 em jogadas de ataque, CA e testes de resistência quando tem a torcida a seu favor, durante uma luta ou outro tipo de disputa. Entenda-se por “torcida” qualquer número de pessoas ou criaturas inteligentes (mesmo que seja apenas uma!) que não está realizando nenhuma outra ação além de ver a luta. Você só recebe este benefício quando a maioria das pessoas presentes na cena está gritando seu nome ou torcendo por sua vitória.', '', 'A reação de uma torcida depende do mestre, mas você pode tentar um teste de Atuação ou Diplomacia (CD 20) como uma ação padrão para cair nas graças dos torcedores.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('dd18c3a7-8f84-4bd3-97c1-e50554bf9090', 'Trespassar', 'Quando você derruba um inimigo, pode continuar o golpe e acertar outro alvo.', 'Quando você derruba um inimigo, pode continuar o golpe e acertar outro alvo.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 13, Ataque Poderoso.', 'Quando você derruba um inimigo com um ataque corpo-a-corpo (reduzindo seus PV para 0 ou menos), pode realizar um ataque adicional contra outra criatura adjacente. O ataque adicional usa os mesmos bônus de ataque e dano do ataque original.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('103612e0-63d4-43d3-ab25-3252a262d2b4', 'Trespassar Aprimorado', 'Você empunha suas armas com tanta força que um golpe seu pode derrubar diversos inimigos.', 'Você empunha suas armas com tanta força que um golpe seu pode derrubar diversos inimigos.', 'Tormenta RPG', 0, 'feature', 'Combate', 'For 13, Ataque Poderoso, Trespassar, bônus base de ataque +4.', 'Você pode usar o talento Trespassar quantas vezes quiser na mesma rodada.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('c18b76c4-ea32-43ac-b77f-39c4860ae03b', 'Usar Armas Simples', 'Você foi treinado para usar todas as armas simples, como adaga e bordão.', 'Você foi treinado para usar todas as armas simples, como adaga e bordão.', 'Tormenta RPG', 0, 'feature', 'Geral', '', 'Você sabe usar armas simples.', 'Um personagem atacando com uma arma que não saiba usar sofre penalidade de –4 em jogadas de ataque.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('ef600921-7157-4028-8ff0-4d238216ab2a', 'Usar Armas Marciais', 'Você foi treinado para usar todas as armas marciais, como espada longa e machado de guerra.', 'Você foi treinado para usar todas as armas marciais, como espada longa e machado de guerra.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Usar Armas Simples.', 'Você sabe usar armas marciais.', 'Um personagem atacando com uma arma que não saiba usar sofre penalidade de –4 em jogadas de ataque.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('a3736031-d811-48e8-a6c1-d431422a2641', 'Usar Arma Exótica', 'Escolha uma arma exótica, como katana ou pistola. Você foi treinado para usar esta arma.', 'Escolha uma arma exótica, como katana ou pistola. Você foi treinado para usar esta arma.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Usar Armas Simples.', 'Você sabe usar a arma escolhida.', 'Um personagem atacando com uma arma que não saiba usar sofre penalidade de –4 em jogadas de ataque.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('65f7b290-b4f4-4d2e-aaa9-221e33f06525', 'Usar Armaduras Leves', 'Você foi treinado para usar armaduras leves.', 'Você foi treinado para usar armaduras leves.', 'Tormenta RPG', 0, 'feature', 'Geral', '', 'Você sabe usar armadura acolchoada, corselete de couro, couro batido, camisa de cota de malha e outras armaduras leves.', 'Um personagem vestindo uma armadura que não saiba usar aplica sua penalidade de armadura em jogadas de ataque e testes de perícias baseadas em Força e Destreza.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6ef51105-4d05-46e7-95dc-804885a5eee4', 'Usar Armaduras Médias', 'Você foi treinado para usar armaduras médias.', 'Você foi treinado para usar armaduras médias.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Usar Armaduras Leves', 'Você sabe usar cota de escamas, cota de malha, couraça, gibão de peles e outras armaduras médias.', 'Um personagem vestindo uma armadura que não saiba usar aplica sua penalidade de armadura em jogadas de ataque e testes de perícias baseadas em Força e Destreza.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('800e3fdb-9bbe-44b9-8326-fcdb12088772', 'Usar Armaduras Pesadas', 'Você foi treinado para usar armaduras pesadas.', 'Você foi treinado para usar armaduras pesadas.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Usar Armaduras (leves, médias)', 'Você sabe usar loriga segmentada, meia armadura, armadura completa e outras armaduras pesadas.', 'Um personagem vestindo uma armadura que não saiba usar aplica sua penalidade de armadura em jogadas de ataque e testes de perícias baseadas em Força e Destreza.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d79704e3-5e64-4888-a6d4-3284c10ff5de', 'Usar Escudos', 'Você sabe lutar com escudos.', 'Você sabe lutar com escudos.', 'Tormenta RPG', 0, 'feature', 'Geral', '', 'Você sabe usar escudos leves e pesados.', 'Um personagem equipado com um escudo que não saiba usar sofre penalidade de –4 em jogadas de ataque e testes de perícias baseadas em Força e Destreza.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('cae1608a-a679-4aa6-ba77-a1599bdef3e8', 'Usar Venenos', 'Você faz o que muitos consideram desleal: usar venenos para deixar suas armas mais perigosas.', 'Você faz o que muitos consideram desleal: usar venenos para deixar suas armas mais perigosas.', 'Tormenta RPG', 0, 'feature', 'Geral', 'Treinado em Ofício (alquimia), tendência não Bondosa.', 'Você pode aplicar veneno em armas sem risco de se envenenar acidentalmente.', 'Um personagem sem este talento que aplique veneno em uma arma tem 10% de chance de expor-se acidentalmente ao veneno.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('e2db2bb2-bebe-4755-b725-fe70fa7c3cac', 'Vitalidade', 'Você suporta mais ferimentos que outras pessoas.', 'Você suporta mais ferimentos que outras pessoas.', 'Tormenta RPG', 0, 'feature', 'Geral', '', 'Você recebe 1 ponto de vida adicional por nível de personagem. Quando sobe de nível, os PV que recebe por este talento aumentam de acordo. Por exemplo, se escolher este talento no 3º nível, recebe 3 PV. Chegando ao 4º nível, recebe +1 PV, e assim por diante.', '', 'Você pode escolher este talento diversas vezes. Seus efeitos se acumulam.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('52abd169-5df2-4980-81e8-7bea079dbb6a', 'Acrobacia Audaz', 'Você consegue atravessar aposentos lotados ou mobiliados, correndo sobre mesas, escorregando por corrimões de escada, balançando-se em candelabros ou até pisando sobre outras pessoas!', 'Você consegue atravessar aposentos lotados ou mobiliados, correndo sobre mesas, escorregando por corrimões de escada, balançando-se em candelabros ou até pisando sobre outras pessoas!', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Treinado em Acrobacia.', 'Você pode atravessar terrenos difíceis sem sofrer redução em seu deslocamento. Você pode realizar investidas mesmo nessas condições.', 'Um personagem em terreno difícil tem seu deslocamento reduzido à metade, e não pode realizar investidas.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('5d7a7c94-0e6a-403a-8794-7dba9f29aa0d', 'Acrobático', 'Você tropeça menos que os outros.', 'Você tropeça menos que os outros.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Acrobacia que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('a5f467a1-de42-4cea-9593-73660d17eb6c', 'Afinidade com Animais', 'Você se dá bem com animais.', 'Você se dá bem com animais.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Adestrar Animais que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d5fb97bc-0543-4839-8a6e-a49b99cf59a2', 'Ágil', 'Você pode usar sua agilidade para realizar proezas acrobáticas.', 'Você pode usar sua agilidade para realizar proezas acrobáticas.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Des 15.', 'Você pode usar seu modificador de Destreza em vez de Força em testes de Atletismo.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d69d2e95-9aa6-451f-9a4f-93025108c0e8', 'Aptidão Mágica', 'Você tem um dom natural para as artes místicas.', 'Você tem um dom natural para as artes místicas.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Identificar Magia que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('2e78df6d-5c26-4b47-b5a2-3e48b15bf963', 'Artista', 'Você tem jeito para as artes.', 'Você tem jeito para as artes.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Atuação que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('c9bb644f-5bbb-4eaf-be0a-8c57f2e9acea', 'Atlético', 'Você tem aptidão natural para atividades físicas.', 'Você tem aptidão natural para atividades físicas.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Atletismo que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('4ff9efcd-4b18-40e8-99d3-5984f6154be9', 'Autossuficiente', 'Você se vira bem sozinho.', 'Você se vira bem sozinho.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você não sofre a penalidade de –5 para fazer testes de Cura em si mesmo, e recebe +4 nos testes de Sobrevivência se estiver sozinho (sem nenhum aliado a até 18m).', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('f0408f99-1e17-42eb-a607-8c6cc58454ca', 'Criar Obra-Prima', 'Você é um artesão competente e pode criar itens de qualidade excepcional.', 'Você é um artesão competente e pode criar itens de qualidade excepcional.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Treinado em Ofício, Foco em Perícia (Ofício).', 'Você pode construir armas, armaduras e kits de ferramentas de qualidade obra-prima. Uma arma obra-prima fornece +1 em jogadas de ataque; uma armadura obra-prima tem sua penalidade de armadura reduzida em 1; e um kit de ferramentas obra-prima fornece +2 nos testes da perícia apropriada. Para criar um item obra-prima, siga as regras normais para criação de itens, exceto que a dificuldade do teste de Ofício aumenta em CD+5, e o custo de criação do item aumenta em +100 TO.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d46c9a71-a53c-43bf-944f-6b910ce85b9c', 'Dedos Ágeis', 'Você tem mão leve.', 'Você tem mão leve.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Ladinagem que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6f2f2fad-5868-41fb-b22d-e97c749b9a78', 'Diligente', 'Você é paciente e detalhista.', 'Você é paciente e detalhista.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode gastar uma ação de movimento para se concentrar na tarefa à frente. Se fizer isso, recebe +2 nos testes de perícia realizados até a próxima rodada.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('da315d3b-18dd-40bd-bdf6-6dced2632535', 'Foco em Perícia', 'Escolha uma perícia. Você tem certo dom com ela.', 'Escolha uma perícia. Você tem certo dom com ela.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Treinado na perícia escolhida.', 'Você recebe +4 em testes da perícia escolhida.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('3a5de700-e625-459c-9053-06bd3375cb5b', 'Fraudulento', 'Você sabe como encobrir a verdade.', 'Você sabe como encobrir a verdade.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Enganação que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('15ae2caf-e524-45b0-8c3f-89243f6208e4', 'Impostor', 'Você pode, de forma quase sobrenatural, fingir ter habilidades que não tem. E você finge tão bem que consegue fazer essas coisas!', 'Você pode, de forma quase sobrenatural, fingir ter habilidades que não tem. E você finge tão bem que consegue fazer essas coisas!', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Car 13, Foco em Perícia (Enganação).', 'Graças a seu extremo charme, magnetismo pessoal e superconfiança, você consegue convencer as pessoas (e também a si próprio!) de que tem certas habilidades ou conhecimentos, quando na verdade não tem. Você pode substituir um teste de qualquer perícia por um teste de Enganação. Você pode usar este talento um número de vezes por dia igual a seu bônus de Carisma.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('db857ade-f382-44ab-b515-f781c4076944', 'Iniciativa Aprimorada', 'Você não perde tempo em situações de combate.', 'Você não perde tempo em situações de combate.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Iniciativa que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('11a50607-0110-4b34-b5e5-5468d3bdb32a', 'Investigador', 'Você é um bom detetive.', 'Você é um bom detetive.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Int 13.', 'Você pode somar seu bônus de Inteligência a testes de Obter Informação e testes de Percepção para procurar.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('7f0b33f3-c610-4095-90f1-801130c0966b', 'Mãos Rápidas', 'Quando os outros percebem, já foram roubados.', 'Quando os outros percebem, já foram roubados.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Des 15, treinado em Ladinagem.', 'Uma vez por rodada, você pode fazer um teste de Ladinagem para prestidigitação como uma ação livre.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('3475bbea-9021-48b6-bba7-79c062f2cfb4', 'Negociador', 'Você sabe barganhar.', 'Você sabe barganhar.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Treinado em Ofício.', 'Quando você chega a uma comunidade, faça um teste de Ofício (CD 20). Se tiver sucesso, você pode comprar itens nesta comunidade por 75% do preço padrão (arredondado para baixo). Por exemplo, você pode comprar uma armadura completa (que normalmente custa 1.500 TO) por 1.125 TO. Se falhar, você pode tentar novamente em um mês (ou quando visitar outra comunidade).', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d6b80928-9a75-4288-a6ea-6282e942c8f4', 'Persuasivo', 'Você sabe ser convincente.', 'Você sabe ser convincente.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Diplomacia que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('2ad01bdb-7907-4ed3-8a32-aeb7646f6f4f', 'Prontidão', 'Seus sentidos são mais apurados que o normal.', 'Seus sentidos são mais apurados que o normal.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Percepção que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('a93b0ebd-d7fc-4368-9c4d-8017bcc7bc56', 'Rastrear', 'Você recebeu treinamento para seguir rastros.', 'Você recebeu treinamento para seguir rastros.', 'Tormenta RPG', 0, 'feature', 'Perícia', 'Treinado em Sobrevivência.', 'Você pode fazer testes de Sobrevivência para encontrar rastros. A dificuldade varia de acordo com o solo — CD 10 para solo macio (neve, lama), 15 para solo padrão (grama, terra) e 20 para solo duro (rocha ou piso de interiores). Você ganha +1 para cada três criaturas no grupo sendo seguido. Você sofre uma penalidade de –1 para cada dia desde a criação dos rastros e uma penalidade de –5 em visibilidade precária (noite, chuva, neblina). Você precisa fazer um teste para encontrar os rastros e mais um para cada dia de perseguição. Se falhar você pode tentar novamente gastando mais um dia (mas lembre-se de que a CD aumenta a cada dia).', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('da5492c9-a88d-4426-a83b-ea622dbe02b9', 'Senso da Natureza', 'Você sabe como viver em áreas selvagens.', 'Você sabe como viver em áreas selvagens.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Sobrevivência que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('5a653471-4217-4c0c-8f75-91d190ae7101', 'Sorrateiro', 'Você é bom em passar despercebido.', 'Você é bom em passar despercebido.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você pode rolar outra vez um teste de Furtividade que tenha recém realizado. Você deve aceitar a segunda rolagem, mesmo que seja pior que a primeira.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('69a7fe35-2f47-483f-a86f-425a42bdb5c3', 'Treino em Perícia', 'Escolha uma perícia na qual você não seja treinado. Você se dedicou a esta perícia.', 'Escolha uma perícia na qual você não seja treinado. Você se dedicou a esta perícia.', 'Tormenta RPG', 0, 'feature', 'Perícia', '', 'Você se torna treinado na perícia escolhida.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('1ee1a0e3-5d70-4757-a6ec-2115d8819345', 'Acelerar Magia', '[metamágico] Você pode lançar magias mais rapidamente. Custo: +4 PM.', '[metamágico] Você pode lançar magias mais rapidamente. Custo: +4 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Quando você usa este talento, pode lançar uma magia como uma ação livre. Lançar uma magia acelerada não deixa você desprevenido. Você só pode usar este talento uma vez por rodada. Magias com um tempo de execução maior que uma ação completa não são afetadas por este talento.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('a874dbb9-6efa-4349-b7c0-dab0d943d5db', 'Ampliar Magia', '[metamágico] Você pode fazer com que uma magia afete uma área maior. Custo: +3 PM.', '[metamágico] Você pode fazer com que uma magia afete uma área maior. Custo: +3 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Quando você usa este talento, a área da magia é duplicada (por exemplo, uma bola de fogo ampliada tem 12m de raio, em vez de 6m). Magias sem área de efeito não são afetadas por este talento.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('bfff0b55-a1aa-4f67-9f01-5cde77ee2e9c', 'Aumentar Magia', '[metamágico] Você pode aumentar o alcance de uma magia. Custo: +1 PM.', '[metamágico] Você pode aumentar o alcance de uma magia. Custo: +1 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Quando você usa este talento, o alcance da magia é duplicado (por exemplo, um relâmpago aumentado tem um alcance de 90m, em vez de 45m). Magias sem alcance medido em metros não podem ser afetadas por este talento.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('dfe1a339-036a-4f69-984d-98422c7bec27', 'Conhecimento Mágico', 'Você estudou para aumentar seu repertório de magias.', 'Você estudou para aumentar seu repertório de magias.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Você aprende mais duas magias de quaisquer níveis que possa lançar. Por exemplo, se você é um mago de 3º nível, pode aprender duas magias novas de 1º ou 2º nível.', '', 'Você pode escolher este talento diversas vezes. Cada vez, você aprende duas novas magias.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('94b71194-8ab2-48ce-8277-0eeae0afd8c7', 'Contramágica Aprimorada', 'Você sabe contra-atacar uma magia com mais eficiência.', 'Você sabe contra-atacar uma magia com mais eficiência.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Você pode usar qualquer magia como contramágica, desde que seu custo em PM seja igual ou superior ao custo da magia que você quer anular.', 'Um personagem sem este talento só pode usar como contramágica uma magia igual à que ele quer anular.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('91c2609a-ef8e-40fd-8e4c-04d89ad652cf', 'Dominar Magia', 'Escolha uma magia. Você tem mais familiaridade com ela.', 'Escolha uma magia. Você tem mais familiaridade com ela.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'O custo em PM para lançar a magia escolhida diminui em 1. O custo final (após aplicar todos os modificadores, incluindo este talento e talentos metamágicos) é no mínimo 1 PM.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('de7cea1e-ca3c-4494-b7f5-60e641ba06b5', 'Elevar Magia', '[metamágico] Você pode tornar uma magia mais poderosa. Custo: +1 PM por nível que se deseja aumentar.', '[metamágico] Você pode tornar uma magia mais poderosa. Custo: +1 PM por nível que se deseja aumentar.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Uma magia elevada tem um nível de magia mais alto que o normal (até um máximo de 9º nível). Diferente de outros talentos metamágicos, Elevar Magia aumenta verdadeiramente o nível da magia. Todos os efeitos dependentes de nível (como CD para resistir) são calculados de acordo com o nível elevado.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('4e4f7e0a-043e-4bf6-a73c-1d7af2061536', 'Estender Magia', '[metamágico] Você sabe fazer com que uma magia dure mais tempo. Custo: +1 PM.', '[metamágico] Você sabe fazer com que uma magia dure mais tempo. Custo: +1 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'A duração da magia é duplicada (por exemplo, um imobilizar pessoa estendido dura 2 minutos, em vez de 1 min). Magias com duração instantânea, permanente ou concentração não podem ser afetadas por este talento.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('766b4ef7-34c2-4439-bc4c-b611ec4e3245', 'Familiar', 'Você possui um animal de estimação mágico.', 'Você possui um animal de estimação mágico.', 'Tormenta RPG', 0, 'feature', 'Magia', 'Capacidade de lançar magias arcanas.', 'Você recebe a habilidade familiar do mago. Consulte a descrição da classe mago para mais detalhes.', '', 'Um mago que já possua a habilidade de classe familiar não pode escolher este talento.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('5b4764c7-a728-4d23-8a7a-a4e49a26befe', 'Foco em Magia', 'Escolha uma magia. Quando você lança essa magia, é difícil que seus inimigos resistam ao efeito.', 'Escolha uma magia. Quando você lança essa magia, é difícil que seus inimigos resistam ao efeito.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'A dificuldade do teste de resistência contra a magia escolhida aumenta em CD+2.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('e099547d-a5bc-4664-82a6-504e34ae4c30', 'Foco em Magia Aprimorado', 'Escolha uma magia. Quando você lança essa magia, é muito difícil que seus inimigos resistam ao efeito.', 'Escolha uma magia. Quando você lança essa magia, é muito difícil que seus inimigos resistam ao efeito.', 'Tormenta RPG', 0, 'feature', 'Magia', 'Foco em Magia com a magia escolhida.', 'O aumento de dificuldade oferecido pelo talento Foco em Magia aumenta para CD+4.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('0dfc7f78-c907-43db-9bcf-e29a49b992b7', 'Magia Natural', 'Você pode lançar magias mesmo quando transformado em outra criatura.', 'Você pode lançar magias mesmo quando transformado em outra criatura.', 'Tormenta RPG', 0, 'feature', 'Magia', 'Sab 13, habilidade de forma selvagem.', 'Você pode lançar magias quando está na forma selvagem.', 'Um personagem sem este talento não pode usar magias quando está na forma selvagem.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('94e24b2a-38c6-40bf-b2d4-9ec8820362b8', 'Magia Sem Gestos', '[metamágico] Você consegue lançar magias sem gestos. Custo: +1 PM.', '[metamágico] Você consegue lançar magias sem gestos. Custo: +1 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Uma magia sem gestos pode ser lançada sem nenhum componente gestual.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d32b5ef0-76ad-492b-bed0-03d02bb9c73b', 'Magia Silenciosa', '[metamágico] Você consegue lançar magias sem falar. Custo: +1 PM.', '[metamágico] Você consegue lançar magias sem falar. Custo: +1 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Uma magia silenciosa pode ser lançada sem nenhum componente verbal.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('1fc5e50c-0a6b-4885-af61-dde3efb3894d', 'Magias em Combate', 'Você é habilidoso ao lançar magias em situações de perigo.', 'Você é habilidoso ao lançar magias em situações de perigo.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Você não fica desprevenido quando lança uma magia.', 'Um personagem sem este talento fica desprevenido até seu próximo turno quando lança uma magia.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('8f63c446-53a0-4e15-ae8a-fe317d301942', 'Mago de Batalha', 'Você se especializou em magias de combate, e sabe como aumentar o poder delas.', 'Você se especializou em magias de combate, e sabe como aumentar o poder delas.', 'Tormenta RPG', 0, 'feature', 'Magia', 'Int 13, Magias em Combate, mago 4º nível.', 'Você soma seu modificador de Inteligência às jogadas de dano de suas magias.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('add41667-6082-4101-8b0a-0aacb24ab1c0', 'Maximizar Magia', '[metamágico] Você consegue fazer com que suas magias tenham efeito máximo. Custo: +3 PM.', '[metamágico] Você consegue fazer com que suas magias tenham efeito máximo. Custo: +3 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Quando você usa este talento, todos os efeitos numéricos variáveis da magia são aumentados ao máximo. Por exemplo, uma bola de fogo capaz de causar 6d6 pontos de dano, quando maximizada, causará 36 pontos de dano (mais quaisquer bônus), sem a necessidade de rolar dados. Uma magia sem efeitos variáveis não pode ser afetada por este talento. Uma magia potencializada e maximizada adquire os benefícios separados de cada talento: o resultado máximo, mais metade do resultado jogado normalmente.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('127501f0-5cb3-4346-a129-cab3965c99e2', 'Poder Mágico', 'Você tem uma parcela maior de poder mágico.', 'Você tem uma parcela maior de poder mágico.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Você recebe 1 ponto de magia adicional.', '', 'Você pode escolher este talento diversas vezes. Cada vez que ele é escolhido além da primeira, os pontos de magia fornecidos pelo talento aumentam em +1. Por exemplo, um personagem que tenha escolhido Poder Mágico três vezes recebe um total de 6 PM adicionais (1 PM pela primeira vez, 2 PM pela segunda e 3 PM pela terceira).');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('ddcdcb22-0ff9-405e-aad6-708725d036c5', 'Potencializar Invocação', 'As criaturas que você invoca são mais poderosas.', 'As criaturas que você invoca são mais poderosas.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'As criaturas que você invoca com as magias invocar recebem +2 em suas jogadas de ataque e dano.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('64cebfc4-5dfa-4d46-ac1f-c880c7980d5e', 'Potencializar Magia', '[metamágico] Você faz com que suas magias tenham efeito maior. Custo: +2 PM.', '[metamágico] Você faz com que suas magias tenham efeito maior. Custo: +2 PM.', 'Tormenta RPG', 0, 'feature', 'Magia', '', 'Quando você usa este talento, todos os efeitos numéricos variáveis da magia são aumentados em 50%. Por exemplo, um relâmpago capaz de causar 6d6 pontos de dano, após rolar 21, causa mais 50% (neste caso, 10), para um total de 31 pontos de dano. Quaisquer bônus que você tenha também são potencializados. Uma magia sem efeitos variáveis não pode ser afetada por este talento. Uma magia potencializada e maximizada adquire os benefícios separados de cada talento: o resultado máximo, mais metade do resultado jogado normalmente.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('cdd9df2c-8ba3-4eb6-9daa-4531de420a02', 'Ajuda dos Ancestrais', 'Você pode orar aos espíritos de seus ancestrais e perguntar a eles sobre seu destino.', 'Você pode orar aos espíritos de seus ancestrais e perguntar a eles sobre seu destino.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Sab 13.', 'Você pode lançar a magia adivinhação uma vez por dia, sem gastar pontos de magia.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('97add6a6-4588-4047-a9e3-6ed7891153f3', 'Ao Sabor do Destino', 'Alguns dias são da caça, outros do caçador. Alguns dias são do fora da lei e outros do oficial da lei! Se hoje você está carregado de tesouros, amanhã pode estar fugindo pela vida com as calças na mão...', 'Alguns dias são da caça, outros do caçador. Alguns dias são do fora da lei e outros do oficial da lei! Se hoje você está carregado de tesouros, amanhã pode estar fugindo pela vida com as calças na mão e estômago roncando. Outros confiam em equipamento mágico. Mas você confia apenas em sua própria habilidade e sorte.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Car 13, personagem 5º nível.', 'Você recebe os seguintes benefícios, de acordo com seu nível de personagem. Caso adquira este talento depois do 5º nível, você recebe todos os benefícios dos níveis anteriores. 5º +1 em jogadas de ataque e dano. 6º +4 em uma perícia à sua escolha. 7º +1 na CA. 8º +2 em uma habilidade à sua escolha (cumulativo). 9º +1 nos testes de resistência. 10º +2 em jogadas de ataque e dano. 11º +4 em uma perícia à sua escolha. 12º +2 na CA. 13º +2 em uma habilidade à sua escolha (cumulativo). 14º +2 nos testes de resistência. 15º +3 em jogadas de ataque e dano. 16º +4 em uma perícia à sua escolha. 17º +3 na CA. 18º +2 em uma habilidade à sua escolha (cumulativo). 19º +3 nos testes de resistência. 20º +4 em jogadas de ataque e dano.', '', 'Quando você utiliza voluntariamente qualquer item mágico (exceto poções), perde o benefício deste talento por um mês. Você ainda pode lançar magias, receber magias benéficas, ou beneficiar-se de itens usados por outros — por exemplo, você pode “ir de carona” em um tapete voador, mas não pode você mesmo conduzi-lo.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('c7b0c658-2c93-4062-9b5f-7fdbeda3e1f8', 'Atraente', 'Olhos bonitos, traços delicados, voz melodiosa... Algo em sua aparência chama à atenção.', 'Olhos bonitos, traços delicados, voz melodiosa... Algo em sua aparência chama à atenção.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Você recebe +4 nos testes de Diplomacia e Enganação contra qualquer um que possa se sentir fisicamente atraído por você.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('c7027372-ce94-495b-8c64-af50a9ca03ee', 'Comandar', 'Você sabe como liderar outros em batalha.', 'Você sabe como liderar outros em batalha.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Car 13.', 'Você pode usar uma ação padrão para gritar ordens para seus aliados. Aqueles que puderem ouvi-lo recebem +1 em suas jogadas e testes por um número de rodadas igual a 1 + seu modificador de Carisma.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('12b8bf6e-e23f-4722-b422-34e995742988', 'Corrida', 'Você corre. Rápido.', 'Você corre. Rápido.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Seu deslocamento aumenta em +3m.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('f7ca3264-6ec7-44e5-ac16-2d564c9a84af', 'Devoto', 'Escolha um deus. Você segue fielmente o deus escolhido, recebendo uma pequena porção de poder mágico divino por isso.', 'Escolha um deus. Você segue fielmente o deus escolhido, recebendo uma pequena porção de poder mágico divino por isso.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Sab 11, estar entre os adoradores típicos do deus escolhido (veja em “Deuses”, no Capítulo 6).', 'Escolha uma magia divina de nível 0. Você pode lançar esta magia até três vezes por dia, como se fosse um clérigo.', '', 'Este talento funciona como a habilidade de classe devoto (de clérigos, druidas e paladinos), permitindo que você adquira talentos de Poder Concedido de sua divindade padroeira. Este talento pode ser adquirido várias vezes. Cada vez que é adquirido, você deve escolher outra magia.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('73634238-3605-4396-ab3b-b8b7c03aac0d', 'Estudioso Arcano', 'Você estudou um pouco sobre magia.', 'Você estudou um pouco sobre magia.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Int 11.', 'Escolha uma magia arcana de nível 0. Você pode lançar esta magia até três vezes por dia, como se fosse um mago.', '', 'Este talento pode ser adquirido várias vezes. Cada vez que é adquirido, você deve escolher outra magia.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('e8c1452d-8776-48a9-a387-71415dbf0941', 'Expulsão Aprimorada', 'Você consegue expulsar ou comandar mortos-vivos com mais eficácia.', 'Você consegue expulsar ou comandar mortos-vivos com mais eficácia.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Expulsar/Fascinar Mortos-Vivos.', 'A dificuldade do teste de Vontade contra o talento Expulsar/Fascinar Mortos-Vivos aumenta em CD+2.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('786a932d-9ca2-452f-a708-b4af83365233', 'Expulsar/Fascinar Mortos-Vivos', 'Você pode usar sua energia positiva para expulsar mortos-vivos, ou energia negativa para fasciná-los.', 'Você pode usar sua energia positiva para expulsar mortos-vivos, ou energia negativa para fasciná-los.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Habilidade de canalizar energia positiva/negativa.', 'Este talento afeta todos os mortos-vivos a até 9m. Se você canaliza energia positiva, pode deixá-los apavorados durante um minuto. Se canaliza energia negativa, pode deixá-los sob seu comando. Dar uma ordem aos mortos-vivos é uma ação de movimento. O nível somado de mortos-vivos sob seu comando não pode exceder seu próprio nível. Mortos-vivos têm direito a um teste de Vontade (CD 10 + metade de seu nível + modificador de Carisma) para evitar qualquer destes efeitos. Usar este talento é uma ação padrão, e gasta uma utilização diária da habilidade canalizar energia positiva/negativa.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('c060d3b9-ccf5-4879-a721-8f312d23ecb1', 'Fortitude Maior', 'Você tem mais resistência física que as pessoas normais.', 'Você tem mais resistência física que as pessoas normais.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Seu bônus base de Fortitude aumenta +2.', '', 'Você pode escolher este talento diversas vezes. Seus efeitos se acumulam.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('24e90cd7-fbbb-41e5-8db0-1fcffa4635e2', 'Liderança', 'Por suas façanhas, você atraiu uma ou mais pessoas que desejam servir a você.', 'Por suas façanhas, você atraiu uma ou mais pessoas que desejam servir a você.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Personagem 6º nível.', 'Escolha entre ter um parceiro, ou ter seguidores. Um parceiro é um segundo personagem, dois níveis abaixo do seu. Você é livre para construir esse personagem, escolhendo sua raça e classe — mas a tendência do parceiro deve estar apenas um passo distante da sua. O parceiro avança de nível quando você também avança. Um parceiro é alguém leal, que segue seu personagem por razões pessoais. Ele segue suas ordens, e pode até arriscar a vida para ajudá-lo. Mas um parceiro constantemente maltratado pode — por intervenção do mestre — desistir de segui-lo. Se escolheu seguidores, você tem uma quantidade de níveis de seguidores igual a seu nível multiplicado por seu modificador de Carisma (mínimo 1). Por exemplo, um paladino de 10º nível e Carisma 16 (+3) tem 30 níveis de seguidores. Você pode distribuir os níveis como quiser para construir os personagens, mas o nível máximo que eles podem ter é igual a metade do seu. Então, o mesmo paladino poderia ter seguidores de até 5º nível. Essa diferença de poder torna os seguidores ineficazes em combate. Em geral eles atuam apenas contra adversários fracos, ou então como ajudantes, guardas, mensageiros, carregadores... Seguidores podem ser de qualquer tendência, mas não costumam ser tão leais ou corajosos quanto parceiros. Podem lutar se ordenados, mas abandonam a luta se perdem metade ou mais de seus pontos de vida. Seguidores não sobem de nível; quando você sobe de nível, ganha mais seguidores. Ao perder parceiros ou seguidores (por morte ou desistência), você vai precisar de 1d4 meses para encontrar outros.', '', 'Você pode escolher este talento duas vezes, uma para parceiro e uma para seguidores.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('9cef8e5f-3c7d-4fdd-a8cc-bdf24737340b', 'Linguista', 'Neste mundo de muitas línguas e culturas, você tem aptidão para aprender idiomas de outros povos.', 'Neste mundo de muitas línguas e culturas, você tem aptidão para aprender idiomas de outros povos.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Você aprende um número de novos idiomas igual a 3 + seu modificador de Inteligência (mínimo 1).', '', 'Você pode escolher este talento diversas vezes. Seus efeitos se acumulam.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6f30330d-d523-4209-a1ea-47ff3ef7af00', 'Reflexos Rápidos', 'Você tem Reflexos apurados.', 'Você tem Reflexos apurados.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Seu bônus base de Reflexos aumenta +2.', '', 'Você pode escolher este talento diversas vezes. Seus efeitos se acumulam.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('671170f8-332a-4fec-b58d-6fefc33fe310', 'Surto Heroico', 'Graças a seu ímpeto de heroísmo, você consegue realizar mais em menos tempo.', 'Graças a seu ímpeto de heroísmo, você consegue realizar mais em menos tempo.', 'Tormenta RPG', 0, 'feature', 'Destino', 'Tendência Bondosa.', 'Você pode realizar uma ação padrão ou de movimento adicional na rodada. Por exemplo, pode realizar uma ação completa e uma ação padrão, ou uma ação padrão e duas ações de movimento, ou qualquer outra combinação. Você pode usar este talento uma vez por dia.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('6272b50f-9a87-4d40-9867-b9c94dbfa096', 'Terreno Familiar', 'Escolha um tipo de terreno entre deserto, floresta, montanhas, pântano, planície, selva, tundra, aquático, subterrâneo ou área de Tormenta. Você é mais habilidoso neste tipo de terreno.', 'Escolha um tipo de terreno entre deserto, floresta, montanhas, pântano, planície, selva, tundra, aquático, subterrâneo ou área de Tormenta. Você é mais habilidoso neste tipo de terreno.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Você recebe +2 na classe de armadura e testes de Acrobacia, Atletismo, Furtividade, Percepção e Sobrevivência quando estiver no tipo de terreno escolhido.', '', 'De acordo com o mestre, você pode escolher um lugar específico como seu terreno familiar, como um vale, uma cidade, uma estrada, um navio... No entanto, você não pode escolher áreas de grande extensão como as Montanhas Sanguinárias, Galrasia, o Rio dos Deuses, ou qualquer das nações do Reinado.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('0e5dbdc0-d929-43dc-ac4d-04381841b0c3', 'Tolerância', 'Você segue em frente mesmo quando os outros já cansaram ou caíram.', 'Você segue em frente mesmo quando os outros já cansaram ou caíram.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Você recebe +4 em testes de Constituição para prender o fôlego e evitar dano por fome ou sede, e em testes de Fortitude para evitar dano por frio ou calor. Você também pode dormir de armadura sem ficar fatigado.', 'Um personagem sem este talento que durma de armadura acorda fatigado no dia seguinte.', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d0a00c82-0510-4d48-8f33-516eafe34e58', 'Vontade de Ferro', 'Você tem uma imensa força de vontade.', 'Você tem uma imensa força de vontade.', 'Tormenta RPG', 0, 'feature', 'Destino', '', 'Seu bônus base de Vontade aumenta +2.', '', 'Você pode escolher este talento diversas vezes. Seus efeitos se acumulam.');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('d170b8a9-aadc-41bc-89e2-b52113c47071', 'Domínio da Água', 'Este talento concede um poder divino relacionado à água.', 'Este talento concede um poder divino relacionado à água.', 'Tormenta RPG', 0, 'feature', 'Poder Concedido', 'Devoto de Oceano ou Wynna.', 'Você está permanentemente sob efeito da magia respirar na água.', '', '');
INSERT INTO public.feature (id, name, resume, description, book, page, type, feature_type, prerequisites, benefit, normal, special) VALUES ('b615265d-05dc-499f-b1f4-458a3e6d7229', 'Domínio dos Animais', 'Este talento concede um poder divino relacionado aos animais.', 'Este talento concede um poder divino relacionado aos animais.', 'Tormenta RPG', 0, 'feature', 'Poder Concedido', 'Devoto de Allihanna, Megalokk ou Oceano.', 'Você está permanentemente sob efeito da magia falar com animais. Além disso, Sobrevivência é uma perícia de classe para você.', '', '');
