INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('e02f33a6-cba0-4327-b86e-5689f8580438', 'Expulsão', 'alvo é expulso para seu plano nativo.', 'alvo é expulso para seu plano nativo.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Abjuração', '5', '', '1 Ação Padrão', '', 'Alvo', '', '', '', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('09389abc-3ffe-4959-b0bd-2e611e295bd8', 'Abençoar Água', 'Esta magia imbui um frasco de água com energia positiva, transformando-a em água benta (veja o Capítulo 7: Equipamento).', 'Esta magia imbui um frasco de água com energia positiva, transformando-a em água benta (veja o Capítulo 7: Equipamento).', 'Tormenta RPG', 0, 'magic', 'Divina', 'Cura', '1', '2,5kg de prata em pó (no valor de 25 TO)', '1 minuto', 'toque', '1 frasco de água', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('e30c48f8-6c3d-40dc-95a7-6ec38661e68e', 'Abrir/Fechar', 'Você pode abrir ou fechar uma porta, baú, garrafa, bolsa, etc. Esta magia não afeta objetos trancados.', 'Você pode abrir ou fechar uma porta, baú, garrafa, bolsa, etc. Esta magia não afeta objetos trancados.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Transmutação', '0', 'nenhum', 'ação de movimento', '9m', '1 objeto de até 20kg que possa ser aberto ou fechado', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('1386fbc2-e4db-4525-aa3b-010decba449d', 'Acalmar Animal', 'Esta magia acalma um animal, deixando-o dócil e inofensivo. Qualquer ameaça óbvia anula a magia.', 'Esta magia acalma um animal, deixando-o dócil e inofensivo. Qualquer ameaça óbvia anula a magia.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Encantamento', '1', 'nenhum', 'ação padrão', '9m', '1 animal', '1 minuto', 'Vontade anula', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('fa272b9b-e15c-41af-8af0-ec77dddd01f4', 'Acalmar Emoções', 'Esta magia acalma as criaturas na área, que não podem atacar ou realizar qualquer tipo de ação agressiva (but they can defend normally). Qualquer ameaça óbvia anula a magia.', 'Esta magia acalma as criaturas na área, que não podem atacar ou realizar qualquer tipo de ação agressiva (but they can defend normally). Qualquer ameaça óbvia anula a magia.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Encantamento', '2', 'nenhum', 'ação padrão', '30m', 'dispersão com 6m de raio', 'concentração, até 1 minuto', 'Vontade anula', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('e677f270-5fe8-43b5-8fc4-d59d5fc1d970', 'Adivinhação', 'Esta magia responde uma pergunta feita por você. O mestre deve rolar 1d6; com um resultado de 1 a 5 a adivinhação funciona, e você recebe sua resposta, que pode ser desde uma simples frase até uma pro...', 'Esta magia responde uma pergunta feita por você. O mestre deve rolar 1d6; com um resultado de 1 a 5 a adivinhação funciona, e você recebe sua resposta, que pode ser desde uma simples frase até uma profecia ou enigma. Em um resultado de 6 a adivinhação falha, e você não recebe resposta alguma. Você não pode lançar mais de uma adivinhação para a mesma pergunta. Adivinhação não é poderosa o suficiente para resolver tramas intrincadas — como regra geral, qualquer coisa que exija mais de um dia de investigação não será capaz de descobrir a resposta que procura.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Adivinhação', '4', 'incenso e oferendas sacrificadas à sua divindade, no valor de pelo menos 100 TO.', '10 minutos', 'pessoal', 'você', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('adb863a1-4a50-4add-aa80-a6ca9e41bfc2', 'Agilidade do Gato', 'Esta magia torna o alvo mais gracioso, coordenado e ágil, fornecendo um bônus de +4 na Destreza.', 'Esta magia torna o alvo mais gracioso, coordenado e ágil, fornecendo um bônus de +4 na Destreza.', 'Tormenta RPG', 0, 'magic', 'Universal', 'Transmutação', '2', 'nenhum', 'ação padrão', 'toque', '1 criatura', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('d396a0b4-39a6-402a-bb61-9eb67e63d5b4', 'Agilidade do Gato em Massa', 'Como agilidade do gato, mas afeta até cinco criaturas.', 'Como agilidade do gato, mas afeta até cinco criaturas.', 'Tormenta RPG', 0, 'magic', 'Universal', 'Transmutação', '6', 'nenhum', 'ação padrão', '9m', 'até 5 criaturas', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('9c9beb5b-1e41-4b71-95e8-25e89605a363', 'Ajuda', 'Esta magia concede ao alvo um bônus de +1 nas jogadas de ataque e testes de resistência contra medo, além de 1d8+1 PV temporários. PV temporários são os primeiros a serem perdidos quando o alvo sofre ...', 'Esta magia concede ao alvo um bônus de +1 nas jogadas de ataque e testes de resistência contra medo, além de 1d8+1 PV temporários. PV temporários são os primeiros a serem perdidos quando o alvo sofre dano, e desaparecem quando a magia termina.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Cura', '2', 'nenhum', 'ação padrão', 'toque', '1 criatura', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('078aa091-0591-4ef2-aa49-14446e4934ae', 'Alarme', 'Alarme emite um aviso telepático ou sonoro (decidido quando a magia é lançada) sempre que uma criatura Diminuta ou maior invadir ou tocar a área protegida. Um aviso telepático alerta apenas o conjurad...', 'Alarme emite um aviso telepático ou sonoro (decidido quando a magia é lançada) sempre que uma criatura Diminuta ou maior invadir ou tocar a área protegida. Um aviso telepático alerta apenas o conjurador, inclusive acordando-o se ele estiver dormindo, mas apenas se ele estiver a até 1km da área. Um aviso sonoro alerta todos num raio de 30m da área. Uma criatura que diga a senha (decidida quando a magia é lançada) não dispara o alarme.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Abjuração', '1', 'nenhum', 'ação padrão', '9m', 'emanação de 6m de raio centrada em um ponto no espaço', '1 dia', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('4c3af261-efa5-4681-8879-581a04fbb2a7', 'Aliado Extraplanar', 'Como aliado extraplanar menor, mas você invoca um espírito de até 12º nível. Além disso, uma tarefa que exija até um minuto para ser realizada custa 200 TO, uma que exija até um dia custa 1.000 TO e u...', 'Como aliado extraplanar menor, mas você invoca um espírito de até 12º nível. Além disso, uma tarefa que exija até um minuto para ser realizada custa 200 TO, uma que exija até um dia custa 1.000 TO e uma tarefa que exija até uma semana custa 2.000 TO. Custo em XP: 250 XP.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Invocação', '6', 'nenhum', '10 minutos', '9m', '1 espírito de até 12º nível', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('9e0ccc27-2607-4ec7-8134-27793010650c', 'Aliado Extraplanar Maior', 'Como aliado extraplanar menor, mas você invoca um espírito de até 18º nível. Além disso, uma tarefa que exija até um minuto para ser realizada custa 300 TO, uma que exija até um dia custa 1.500 TO e u...', 'Como aliado extraplanar menor, mas você invoca um espírito de até 18º nível. Além disso, uma tarefa que exija até um minuto para ser realizada custa 300 TO, uma que exija até um dia custa 1.500 TO e uma tarefa que exija até uma semana custa 2.500 TO. Custo em XP: 500 XP.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Invocação', '8', 'nenhum', '10 minutos', '9m', '1 espírito de até 18º nível', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('b9c658c9-54ad-41fa-b056-c66e02c985cb', 'Aliado Extraplanar Menor', 'Você pede à sua divindade que envie um espírito para ajudá-lo. Esse espírito realiza uma tarefa à sua escolha — desde algo simples como “use suas asas para nos levar até o topo da montanha” até algo c...', 'Você pede à sua divindade que envie um espírito para ajudá-lo. Esse espírito realiza uma tarefa à sua escolha — desde algo simples como “use suas asas para nos levar até o topo da montanha” até algo complexo como “escolte esses camponeses até o próximo castelo” —, mas exige um pagamento em troca. Uma tarefa que exija até um minuto para ser realizada custa 100 TO, uma que exija até um dia custa 500 TO e uma tarefa que exija até uma semana (o máximo que a criatura ficará) custa 1.000 TO. O tipo de criatura é escolhido pelo mestre. A forma do pagamento varia: doações a uma igreja, um item mágico, Tibares... A criatura retorna ao seu plano natal quando cumpre a tarefa.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Invocação', '4', 'nenhum', '10 minutos', '9m', '1 espírito de até 6º nível', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('3ace2d15-ee97-4319-8c66-5204a03cdf27', 'Alterar Forma', 'Você pode mudar sua aparência e forma — inclusive roupas e equipamento — para qualquer outra criatura, no máximo, uma categoria de tamanho menor ou maior. Você mantém suas estatísticas, mas recebe uma...', 'Você pode mudar sua aparência e forma — inclusive roupas e equipamento — para qualquer outra criatura, no máximo, uma categoria de tamanho menor ou maior. Você mantém suas estatísticas, mas recebe uma habilidade da forma selvagem do druida (veja o Capítulo 2: Classes). Se sua nova forma não é capaz de falar ou não tem membros capazes de fazer gestos precisos, você não pode lançar magias até voltar a sua forma normal. Se usar esta magia para criar um disfarce, você recebe +10 no teste de Enganação.', 'Tormenta RPG', 0, 'magic', 'Universal', 'Transmutação', '9', 'nenhum', 'ação padrão', 'pessoal', 'você', '1 hora (D)', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('c5d84587-ee81-441b-8fc3-95d3038baf9b', 'Alterar-se de Raviollius', 'Como metamorfose, mas você pode assumir a forma de qualquer criatura, de qualquer tamanho, com até 30 níveis. A cada rodada, você pode usar uma ação de movimento para assumir outra forma.', 'Como metamorfose, mas você pode assumir a forma de qualquer criatura, de qualquer tamanho, com até 30 níveis. A cada rodada, você pode usar uma ação de movimento para assumir outra forma.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Transmutação', '2', 'nenhum', 'ação padrão', 'pessoal', 'você', '1 hora (D)', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('b3b98a3c-2bb0-4af6-b328-a4b2923fe648', 'Amaldiçoar Água', 'Esta magia imbui um frasco de água com energia negativa, transformando-a em água profana. Água profana causa dano a espíritos Bondosos da mesma forma que água benta causa dano a espíritos Malignos.', 'Esta magia imbui um frasco de água com energia negativa, transformando-a em água profana. Água profana causa dano a espíritos Bondosos da mesma forma que água benta causa dano a espíritos Malignos.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Necromancia', '1', '2,5kg de prata em pó (que valem 25 TO)', '1 minuto', 'toque', '1 frasco de água', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('eee1f4ca-1586-4d17-8858-9256804b0fd4', 'Amolecer Terra e Pedra', 'Toda a terra ou pedra natural na área amolece. Terra molhada se torna lama, terra seca se torna pó, e pedra se torna argila. Pedras mágicas ou trabalhadas (como construções) não são afetadas. Uma cria...', 'Toda a terra ou pedra natural na área amolece. Terra molhada se torna lama, terra seca se torna pó, e pedra se torna argila. Pedras mágicas ou trabalhadas (como construções) não são afetadas. Uma criatura na lama deve fazer um teste de Reflexos para não ficar presa por uma rodada. Uma criatura no pó tem seu deslocamento reduzido à metade. A argila pode ser escavada para amolecer uma parede e escapar.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Terra', '2', 'nenhum', 'ação padrão', '9m', '1 quadrado de 9m de lado', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('4afecd79-51dd-4248-a5b6-da62b5a6ec9b', 'Ampliar Animal', 'Esta magia dobra a altura do alvo, o que aumenta seu tamanho em uma categoria e fornece Força +8, Constituição +4, redução de dano 10/mágica e +4 nos testes de resistência. Todo equipamento carregado ...', 'Esta magia dobra a altura do alvo, o que aumenta seu tamanho em uma categoria e fornece Força +8, Constituição +4, redução de dano 10/mágica e +4 nos testes de resistência. Todo equipamento carregado pelo alvo também é afetado. Caso não haja espaço suficiente para a criatura crescer, ela pode fazer um teste de Força (com o bônus fornecido pela magia) para quebrar qualquer barreira (por exemplo, o teto da construção onde estiver). Se o teste falhar a magia não funciona — ampliar animal não pode ser usado para esmagar uma criatura aumentando seu tamanho.', 'Tormenta RPG', 0, 'magic', 'Universal', 'Transmutação', '5', 'nenhum', 'ação padrão', '30m', '1 animal', '10 minutos', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('94f77f47-291d-422b-8023-7a471dc57f67', 'Ampliar Plantas', 'A vegetação da área (grama, arbustos, árvores...) aumenta e se fecha. A área vira terreno difícil. Esta magia também pode ser usada para aumentar a produtividade de uma área cultivada em 50% na próxim...', 'A vegetação da área (grama, arbustos, árvores...) aumenta e se fecha. A área vira terreno difícil. Esta magia também pode ser usada para aumentar a produtividade de uma área cultivada em 50% na próxima colheita. Em áreas rurais, clérigos e druidas lançam esta magia como parte das festividades do plantio.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Transmutação', '3', 'nenhum', 'ação padrão', '90m', 'dispersão com 90m de raio', 'instantânea', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('858a8f32-a7a5-4a12-bf3b-a0b44e415758', 'Amor Incontestável', 'O alvo, se falhar em seu teste de Vontade, se apaixona perdidamente pela primeira criatura em que colocar os olhos. O efeito é semelhante a enfeitiçar pessoa, mas mais poderoso. A vítima será capaz de...', 'O alvo, se falhar em seu teste de Vontade, se apaixona perdidamente pela primeira criatura em que colocar os olhos. O efeito é semelhante a enfeitiçar pessoa, mas mais poderoso. A vítima será capaz de quase qualquer coisa para proteger ou ajudar seu “amor”, até mesmo arriscando sua vida. Caso o alvo seja atacado por seu “amor”, o efeito se dissipa. Em animais assexuados ou criaturas de Inteligência 2 ou menos, o efeito pode ser diferente — a vítima considera a criatura amada como sendo sua mãe!', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Encantamento', '2', 'nenhum', 'ação padrão', 'toque', '1 criatura', '1 dia', 'Vontade anula', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('473938bf-48bf-47f5-8604-bf2abfbdeee5', 'Analisar Encantamento', 'A cada rodada, você pode analisar uma criatura ou objeto. Você descobre todas as magias afetando a criatura ou objeto analisado. No caso de itens mágicos, você descobre como ele funciona, como ativá-l...', 'A cada rodada, você pode analisar uma criatura ou objeto. Você descobre todas as magias afetando a criatura ou objeto analisado. No caso de itens mágicos, você descobre como ele funciona, como ativá-lo e quantos PM ele possui (se for o caso).', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Adivinhação', '6', 'nenhum', 'ação padrão', '9m', 'até 10 criaturas ou objetos', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('4944d9ad-538b-4f62-9444-0c446778a75a', 'Âncora Dimensional', 'Você dispara pela mão um raio esverdeado. Faça um ataque de toque à distância. Se acertar, o alvo é envolvido por um campo de força cor de esmeralda que impede qualquer movimento planar. Isso inclui t...', 'Você dispara pela mão um raio esverdeado. Faça um ataque de toque à distância. Se acertar, o alvo é envolvido por um campo de força cor de esmeralda que impede qualquer movimento planar. Isso inclui todas as magias de invocação (como porta dimensional, teletransporte e viagem planar), além de viagens astrais, etéreas ou pelo Plano das Sombras.', 'Tormenta RPG', 0, 'magic', 'Universal', 'Abjuração', '4', 'nenhum', 'ação padrão', '30m', 'raio', '10 minutos', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('e8b22eb7-6c6f-419d-adb8-495b6534c41b', 'Âncora Planar', 'Como âncora planar menor, mas você invoca um espírito de até 12º nível.', 'Como âncora planar menor, mas você invoca um espírito de até 12º nível.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Invocação', '6', 'nenhum', '10 minutos', '9m', '1 espírito de até 12º nível', 'instantânea', 'Vontade anula', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('b0f32fce-c48b-499b-aba9-b855f0342b92', 'Âncora Planar Maior', 'Como âncora planar menor, mas você invoca um espírito de até 18º nível.', 'Como âncora planar menor, mas você invoca um espírito de até 18º nível.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Invocação', '8', 'nenhum', '10 minutos', '9m', '1 espírito de até 18º nível', 'instantânea', 'Vontade anula', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('9e533e26-8976-4e8c-8097-4c6b000d4bac', 'Âncora Planar Menor', 'Você invoca um espírito de até 6º nível, com o qual pode negociar um serviço. Faça um teste oposto de Carisma. Se você vencer, ele executa uma tarefa à sua escolha, com duração máxima de uma semana. S...', 'Você invoca um espírito de até 6º nível, com o qual pode negociar um serviço. Faça um teste oposto de Carisma. Se você vencer, ele executa uma tarefa à sua escolha, com duração máxima de uma semana. Se você perder, ele vai embora. Se você perder por 5 ou mais, ele o ataca. O conjurador pode impedir ataques se lançar um círculo mágico voltado para o interior e invocar a criatura ali dentro (você precisa lançar o círculo mágico antes da âncora planar menor). Se fizer isso o espírito fica preso, e não pode atacá-lo mesmo que você perca o teste oposto de Carisma. Obviamente, você precisará libertar o espírito do círculo para que ele realize a tarefa por você. A criatura tem direito a um teste de Vontade para evitar ser invocada.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Invocação', '5', 'nenhum', '10 minutos', '9m', '1 espírito de até 6º nível', 'instantânea', 'Vontade anula', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('0fdb0a18-7c33-49e5-a156-7ceb89ba61db', 'Andar no Ar', 'O alvo desta magia pode caminhar no ar como se fosse terra sólida. Ele pode andar reto, descer (em ângulo máximo de 45º) usando seu deslocamento normal, ou subir (também em ângulo máximo de 45º) usand...', 'O alvo desta magia pode caminhar no ar como se fosse terra sólida. Ele pode andar reto, descer (em ângulo máximo de 45º) usando seu deslocamento normal, ou subir (também em ângulo máximo de 45º) usando metade de seu deslocamento. De acordo com o mestre, ventos fortes a favor podem empurrar o alvo, dobrando seu deslocamento — ou reduzindo à metade, se forem contra. Quando a magia termina o alvo desce lentamente até o chão, como se estivesse sob efeito de queda suave.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Transmutação', '4', 'nenhum', 'ação padrão', 'toque', '1 criatura', '10 minutos', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('a421bce6-07a5-4cf2-bcf5-983ba4056c06', 'Andar nas Sombras', 'Para lançar esta magia você deve estar em uma área escura. Os alvos são transportados para o Plano das Sombras, uma versão fria e cinzenta do mundo real. No Plano das Sombras as distâncias são distorc...', 'Para lançar esta magia você deve estar em uma área escura. Os alvos são transportados para o Plano das Sombras, uma versão fria e cinzenta do mundo real. No Plano das Sombras as distâncias são distorcidas, e pode-se viajar mais rápido: cada hora de viagem aqui equivale a um dia de viagem no Plano Material. Devido à natureza nublada do Plano das Sombras, é impossível perceber detalhes do terreno e julgar distâncias exatas. Assim, esta magia é inútil para um batedor ou espião. Quando uma criatura sai do Plano das Sombras, surge no lugar equivalente do Plano Material, mas deslocada 1d10 x 30m em uma direção horizontal aleatória.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Ilusão', '6', 'nenhum', 'ação padrão', 'toque', 'até 5 criaturas voluntárias', '1 dia', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('e654496e-c8af-4645-8ffd-7a676e474f5f', 'Animação Ilusória', 'Você cria uma ilusão para esconder o que está acontecendo, tanto de observação direta quanto magias de adivinhação. Quando lança a magia, você escolhe o que vai aparecer na área; qualquer outra coisa ...', 'Você cria uma ilusão para esconder o que está acontecendo, tanto de observação direta quanto magias de adivinhação. Quando lança a magia, você escolhe o que vai aparecer na área; qualquer outra coisa será escondida pela magia. Por exemplo, você pode conjurar a magia sobre um castelo vazio para fazê-lo parecer cheio de soldados, ou sobre uma estrada para ocultar um exército marchando sobre ela. Normalmente, criaturas não têm direito a um teste de Vontade contra esta magia. O teste é permitido apenas se a criatura presenciar algo ilógico — como um exército marchando por uma estrada e subitamente desaparecendo.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Ilusão', '8', 'nenhum', '10 minutos', '9m', '1 cubo de 90m de lado', '1 dia', 'nenhum ou Vontade anula (veja texto)', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('1d82c814-d02e-4b75-8756-acb816d66103', 'Animar Corda', 'Você pode animar uma corda ou objeto similar (corrente, cipó, cabo...). Como uma ação de movimento, você pode fazer a corda se enrolar, fazer um laço ou dar um nó. Se a corda estiver adjacente a uma c...', 'Você pode animar uma corda ou objeto similar (corrente, cipó, cabo...). Como uma ação de movimento, você pode fazer a corda se enrolar, fazer um laço ou dar um nó. Se a corda estiver adjacente a uma criatura Grande ou menor, você pode fazer a corda se enroscar nela. Se falhar em um teste de Reflexos o alvo fica enredado (–2 nas jogadas de ataque, CA, testes de Destreza, perícias baseadas em Destreza e Reflexos, e tem seu deslocamento reduzido à metade). O alvo pode se soltar gastando uma ação completa e sendo bem-sucedido em um teste de Acrobacia (CD 20) ou Força (CD 25). A corda tem 5 pontos de vida.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Transmutação', '1', 'nenhum', 'ação padrão', '9m', '1 corda (ou objeto similar) de até 15m', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('198e6422-37b0-4185-8f91-78613aa481ab', 'Animar Objetos', 'Você concede vida a objetos inanimados, que agem seguindo suas ordens. As estatísticas de um objeto animado dependem de seu tamanho, e são descritas no Capítulo 11: Bestiário. Esta magia não afeta ite...', 'Você concede vida a objetos inanimados, que agem seguindo suas ordens. As estatísticas de um objeto animado dependem de seu tamanho, e são descritas no Capítulo 11: Bestiário. Esta magia não afeta itens mágicos, nem objetos que no momento sejam carregados por uma criatura.', 'Tormenta RPG', 0, 'magic', 'Universal', 'Transmutação', '6', 'nenhum', 'ação padrão', '30m', 'até 8 objetos Pequenos, 4 objetos Médios, 2 objetos Grandes ou 1 objeto Enorme', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('cdf3147f-c650-49fb-b2af-89449fe7b158', 'Animar Plantas', 'Como animar objetos, mas concede movimento a plantas. Elas também usam as estatísticas de objetos animados.', 'Como animar objetos, mas concede movimento a plantas. Elas também usam as estatísticas de objetos animados.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Transmutação', '7', 'nenhum', 'ação padrão', '30m', 'plantas na área', '1 minuto', 'nenhum', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('9e167e2d-64b4-455f-8144-9372f19df87f', 'Antipatia', 'O alvo ou área da magia emite vibrações que repelem um tipo de criatura à sua escolha. Você pode escolher uma raça, como elfos, goblins ou dragões; ou uma tendência, como Leal e Bondoso, ou Caótico e ...', 'O alvo ou área da magia emite vibrações que repelem um tipo de criatura à sua escolha. Você pode escolher uma raça, como elfos, goblins ou dragões; ou uma tendência, como Leal e Bondoso, ou Caótico e Neutro. Criaturas da raça ou tendência escolhidas sentem-se compelidas a se afastar do alvo ou da área. Uma criatura bem-sucedida em um teste de Vontade pode pegar o objeto ou entrar na área, mas sente-se desconfortável fazendo isso, sofrendo penalidade de –4 na Destreza. Antipatia anula simpatia.', 'Tormenta RPG', 0, 'magic', 'Arcana', 'Encantamento', '8', 'nenhum', '1 hora', '9m', '1 objeto ou 1 cubo com 30m de lado', '1 dia', 'Vontade parcial', 'nenhum', '');
INSERT INTO public.magic (id, name, resume, description, book, page, type, magic_type, school, level, components, cast_time, range, target_area, duration, saving_throw, spell_resistance, effect) VALUES ('0c2198cc-02fa-4f3e-bf7d-6daac07e4ce1', 'Antipatia', 'O alvo ou área da magia emite vibrações que repelem um tipo de criatura à sua escolha. Você pode escolher uma raça, como elfos, goblins ou dragões; ou uma tendência, como Leal e Bondoso, ou Caótico e ...', 'O alvo ou área da magia emite vibrações que repelem um tipo de criatura à sua escolha. Você pode escolher uma raça, como elfos, goblins ou dragões; ou uma tendência, como Leal e Bondoso, ou Caótico e Neutro. Criaturas da raça ou tendência escolhidas sentem-se compelidas a se afastar do alvo ou da área. Uma criatura bem-sucedida em um teste de Vontade pode pegar o objeto ou entrar na área, mas sente-se desconfortável fazendo isso, sofrendo penalidade de –4 na Destreza. Antipatia anula simpatia.', 'Tormenta RPG', 0, 'magic', 'Divina', 'Encantamento', '9', 'nenhum', '1 hora', '9m', '1 objeto ou 1 cubo com 30m de lado', '1 dia', 'Vontade parcial', 'nenhum', '');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('7bff7582-c5e8-4900-afb8-506e84e2ecce', 'Anões', '', 'Povo recluso e próximo das montanhas e rochas, os anões habitam o reino subterrâneo de Doherimm, onde escavam ouro, prata e todo tipo de gemas. São gente simples: gostam de esculpir a rocha, trabalhar o metal e entalhar joias — além de uma boa briga e uma cerveja bem tirada! Entre os povos civilizados, não há criatura mais resistente ou difícil de matar que um anão.', 'Tormenta RPG', 0, 'racial_traits', '+4 Constituição, +2 Sabedoria, –2 Destreza. Anões são resistentes e sábios, mas um tanto lentos.\nDeslocamento 6m. Embora sejam seres de tamanho Médio, anões têm pernas curtas e seu deslocamento é o mesmo de criaturas Pequenas. No entanto, o deslocamento de um anão jamais é reduzido por uso de armadura ou excesso de carga.\nVisão no Escuro. Anões podem enxergar no escuro a até 18 metros, apenas em preto e branco. Um anão ignora camuflagem (incluindo camuflagem total) por escuridão.\n+4 em testes de resistência contra venenos e magia.\nPara anões, todos os tipos de machados e martelos são armas simples.\nClasse de armadura +4 contra adversários de tamanho Grande ou maior.\n+2 em testes de perícias para assuntos relacionados a pedra e metal, apenas para perícias com Inteligência ou Sabedoria como habilidade-chave. Este bônus aplica-se a coisas como masmorras, armadilhas, passagens secretas, armas, armaduras, joias e gemas preciosas, objetos de arte...');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('9a342f37-d729-4402-8252-f550acf68f45', 'Elfos', '', 'Esta raça antiga e mágica foi uma das primeiras criadas pelos deuses. São graciosos e sagazes, mas também excessivamente orgulhosos — sempre acreditaram ser melhores que os outros povos, nunca aceitando alianças. Essa arrogância custou-lhes caro quando sua nação foi arrasada por seus inimigos, os goblinoides.', 'Tormenta RPG', 0, 'racial_traits', '+4 Destreza, +2 Inteligência, –2 Constituição. A agilidade e intelecto dos elfos são lendários, embora sejam mais frágeis que os humanos.\nVisão na Penumbra. Um elfo ignora camuflagem (mas não camuflagem total) por escuridão. Elfos podem ver duas vezes mais longe que os humanos em condições de pouca iluminação, como luz das estrelas e tochas.\n+4 em testes de Vontade contra encantamentos. Elfos também são imunes à magia sono.\n+4 em testes de Identificar Magia e Percepção. Elfos têm familiaridade com magia e sentidos apurados.\nA dificuldade do teste de resistência contra magias arcanas lançadas por um elfo aumenta em CD +2.\nElfos sabem usar espadas curtas, espadas longas, floretes e arcos (curtos, longos e compostos). Elfos também recebem Foco em Arma para uma destas armas (à escolha do jogador) como um talento adicional.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('135d8184-b5b7-4d16-8115-709ad52076e8', 'Goblins', '', 'Estes pequenos humanoides são bastante temidos em regiões selvagens, onde espreitam em grandes bandos e atacam humanos. Suas legiões também enchem as fileiras da Aliança Negra dos Goblinoides. No entanto, muitas partes do Reinado os aceitam como cidadãos legítimos — ainda que com desconfiança.', 'Tormenta RPG', 0, 'racial_traits', '+4 Destreza, +2 Constituição, –2 Carisma. Goblins são ágeis e resistentes, mas também rudes.\nTamanho Pequeno. Goblins recebem +1 na classe de armadura, +1 nas jogadas de ataque e +4 em testes de Furtividade, mas precisam usar armas menores.\nDeslocamento 9m. Apesar de pequenos, goblins são rápidos. Seu deslocamento é o mesmo de criaturas Médias.\nVisão no Escuro. Goblins (assim como outros goblinoides) podem enxergar no escuro a até 18 metros, apenas em preto e branco. Um goblin ignora camuflagem (incluindo camuflagem total) por escuridão.\n+4 em testes de Fortitude contra doenças e venenos. Goblins também não precisam fazer testes de Fortitude por ingerir comida estragada.\n+4 em testes de Ladinagem e Ofício (um à escolha do jogador). Goblins estão acostumados a roubar para viver, e têm aptidão natural para engenhocas.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('01971501-70d0-4238-a4a6-20f3545c8d21', 'Halflings', '', 'Se existe um povo amante do conforto, são os halflings. Tão pequenos em ambição quanto no tamanho, só precisam de boa comida, roupas macias e tocas aconchegantes, onde repousam com família e amigos. São um povo tímido — para gente tão pequena, tudo parece mais ameaçador —, mas mesmo assim amistoso e hospitaleiro.', 'Tormenta RPG', 0, 'racial_traits', '+4 Destreza, +2 Carisma, –2 Força. Halflings são acrobáticos e cativantes, mas fisicamente fracos.\nTamanho Pequeno. Halflings recebem +1 na classe de armadura, +1 nas jogadas de ataque e +4 em testes de Furtividade, mas precisam usar armas menores.\n+2 em todos os testes de resistência, por sua sorte incrível.\n+1 em jogadas de ataque com armas de arremesso e fundas. O arremesso de pedras é um esporte popular da raça.\nPara halflings a perícia Atletismo é baseada em Destreza, não em Força.\n+4 em testes de Enganação. Ninguém desconfia de halflings.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('e6e333cd-ec59-4dbd-ace6-8bb56acf8b6a', 'Humanos', '', 'Com sua inesgotável energia, determinação e ambição, os humanos reinam absolutos em Arton. Variantes em tudo que é possível, eles abraçam todas as devoções, bandeiras e causas — podem tornar-se os mais virtuosos heróis, ou mais cruéis vilões.', 'Tormenta RPG', 0, 'racial_traits', '+2 em duas habilidades à escolha do jogador.\n2 perícias treinadas extras, que não precisam ser escolhidas entre suas perícias de classe.\n2 talentos adicionais à escolha do jogador.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('d62cc9cb-8e61-4adc-b959-f89130b9b7ca', 'Lefou', '', 'A mácula da Tormenta sobre Arton tem sido cada vez maior. Não apenas cresce o número de áreas infestadas, mas também a influência do povo da Tormenta — os estranhos lefeu — além de suas fronteiras. Talvez a face mais assustadora dessa influência seja o surgimento dos lefou, os meio--demônios da Tormenta.', 'Tormenta RPG', 0, 'racial_traits', '+2 em duas habilidades à escolha do jogador (exceto Carisma). Lefou têm habilidades acima da média, mas têm problemas de identidade e raramente se destacam em situações sociais.\nMonstro. Um lefou não é considerado humano ou humanoide, sendo imune a magias e efeitos que afetam apenas estas criaturas.\nVisão no escuro. Um lefou ignora camuflagem (incluindo camuflagem total) por escuridão. Lefou enxergam normalmente no escuro, embora apenas em preto e branco.\n2 talentos da Tormenta adicionais. O lefou não perde pontos de Carisma por estes talentos (mas perde se adquirir outros).\nDeformidade. Todo lefou tem algum defeito físico que, embora desagradável aos olhos, confere certa vantagem. O jogador deve escolher uma entre as seguintes. Articulações flexíveis: +4 em testes de Acrobacia. Dedos rígidos: deslocamento de escalada 4,5m. Dentes afiados: +4 em testes de Intimidação. Mãos membranosas: deslocamento de natação 4,5m. Olhos vermelhos: +4 em testes de Percepção. Pele rígida: classe de armadura +1.\nAfinidade com a Tormenta. Um lefou jamais recebe níveis negativos devido a efeitos causados pela Tormenta ou seus habitantes. Ele ainda pode receber níveis negativos de outras formas.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('957694cb-4bac-4a3a-a5dc-9a105608a190', 'Minotauros', '', 'Eles são o povo de Tauron, o Deus da Força e autoproclamado líder do Panteão. São uma raça guerreira e orgulhosa, que venera a força física. Acreditam que seu papel no mundo é proteger e governar os mais fracos.', 'Tormenta RPG', 0, 'racial_traits', '+4 Força, +2 Constituição, –2 Carisma. Minotauros são fortes e resistentes, mas também arrogantes e teimosos.\nClasse de armadura +1. Minotauros têm couro rígido.\nMinotauros possuem um ataque de chifres (1d6, crítico x2, perfuração). Um minotauro pode realizar um ataque adicional por rodada com os chifres, mas provoca uma penalidade de –4 em todos os ataques (incluindo este).\nFaro. Minotauros recebem +4 em testes de Sobrevivência para rastrear usando o faro, e também detectam automaticamente a presença de criaturas a até 9m.\nLógica labiríntica. Minotauros têm excelente senso de direção, e recebem +8 em testes de Sobrevivência para não se perder.\nMedo de altura. Se estiver a 3m ou menos de uma queda de 3m de altura ou mais, um minotauro sofre penalidade de –4 em suas jogadas e testes. Ele também não pode realizar nenhuma ação que dependa de concentração, como lançar magias.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('8e4d7f32-452c-4bc0-bcf2-53c2123d0e18', 'Qareen', '', 'Também conhecidos como meio-gênios, os qareen são descendentes de humanos e seres mágicos — não necessariamente gênios, mas também fadas, ninfas e outros. Os qareen proliferam neste mundo abençoado por Wynna, a bela Deusa da Magia.', 'Tormenta RPG', 0, 'racial_traits', '+4 Carisma, +2 Inteligência, –2 Sabedoria. Qareen são atraentes, simpáticos e brilhantes, embora um pouco ingênuos.\n+4 em testes de Identificar Magia. A natureza mágica dos meio-gênios faz com que eles entendam melhor o funcionamento da magia.\nDesejos. Uma vez por dia, o qareen pode lançar uma magia sem pagar PM (ou sem esquecê-la), mas apenas se fizer isso na mesma rodada em que alguém tiver lhe pedido.\nPequenos desejos. Mesmo que não pertença a uma classe conjuradora, um qareen pode lançar todos os truques (magias arcanas de nível 0) presentes neste livro. No entanto, ele só pode lançar estes truques quando outra pessoa pede.\nUm qareen pode lançar a magia voo uma vez por dia.\nConforme sua descendência, um qareen tem resistência especial contra as seguintes formas de ataque:\nÁgua: resistência a ácido e frio 5.\nAr: resistência a eletricidade e sônico 5.\nFogo: resistência a fogo 5.\nTerra: redução de dano 3/cortante ou perfurante.\nLuz: resistência a eletricidade 10.\nTrevas: resistência a ácido e energia negativa 5. “Energia negativa” é provocada por efeitos e magias necromânticos (como infligir ferimentos).');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('a64827f4-f61e-4f81-b42b-34f54a1f8e7b', 'Gnomos', '', 'Gnomos medem cerca de 1m de altura. São ligeiramente aparentados aos anões, mas ainda menores e menos robustos. Muitos têm orelhas pontiagudas, e quase todos cultivam barbas curtas e bem cuidadas. Gostam de roupas coloridas e joias.', 'Tormenta RPG', 0, 'racial_traits', '+4 Inteligência, +2 Constituição, –2 Força. Gnomos são inteligentes e resistentes, mas também fracos.\nTamanho Pequeno. Gnomos recebem +1 na classe de armadura, +1 nas jogadas de ataque e +4 em testes de Furtividade, mas precisam usar armas menores.\nVisão na Penumbra. Um gnomo ignora camuflagem (mas não camuflagem total) por escuridão. Gnomos podem ver duas vezes mais longe que os humanos em condições de pouca iluminação, como luz das estrelas e tochas.\n+4 em testes de Intuição e Ofícios (alquimia). Gnomos são perspicazes e familiarizados com ilusões e poções.\nClasse de armadura +4 contra adversários de tamanho Grande ou maior.\nGnomos podem se comunicar com animais livremente. Veja a descrição da magia falar com animais.\nUm gnomo com Carisma 10 ou mais pode lançar as seguintes magias livremente: globos de luz, som fantasma, prestidigitação.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('0221cdb6-7e34-4b14-8b00-53bdfbbdfa37', 'Meio-Elfos', '', 'No entanto, talvez você prefira meio-elfos diferenciados — como já ocorria em edições anteriores de Tormenta. Eles podem ser ainda mais trágicos e frustrados que os elfos puros, nascidos da violência. Ou então mais perseverantes, adaptáveis e menos ligados ao passado: criados em famílias humanas normais, adotam atitude positiva e simbolizam a superação da tragédia élfica.', 'Tormenta RPG', 0, 'racial_traits', '+2 Destreza, +2 em outra habilidade à escolha do jogador (exceto Constituição).\nVisão na Penumbra. Um meio-elfo ignora camuflagem (mas não camuflagem total) por escuridão. Meio-elfos podem ver duas vezes mais longe que os humanos em condições de pouca iluminação, como luz das estrelas e tochas.\n1 talento bônus à escolha do jogador.\n1 perícia treinada extra, que não precisa ser escolhida entre suas perícias de classe.\n+2 em testes de Vontade contra encantamentos.\n+2 em testes de Identificar Magia e Percepção.');
INSERT INTO public.racial_traits (id, name, resume, description, book, page, type, traits) VALUES ('43a9f726-6cfa-4585-9fb0-87c8fdd7c51f', 'Meio-Orcs', '', 'A aparência de um meio-orc é apenas um pouco melhor que um orc puro, mas em terras humanas eles ainda podem se fazer passar por “humanos grandes e feios”. Ao contrário dos meio-elfos, meio-orcs em geral são revoltados com sua origem e não querem “pertencer” a lugar nenhum.', 'Tormenta RPG', 0, 'racial_traits', '+2 Força, +2 em outra habilidade à escolha do jogador (exceto Inteligência e Carisma).\nVisão no Escuro. Meio-orcs podem enxergar no escuro a até 18 metros, apenas em preto e branco. Um meio-orc ignora camuflagem (incluindo camuflagem total) por escuridão.\nMeio-orcs recebem Duro de Matar como um talento adicional.\n+4 em testes de Intimidação. Meio-orcs são ameaçadores.');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('decd064a-bde7-5b7b-b4c6-0058a3a2fec8', 'Bárbaro', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('3e504dc3-20b1-4dc4-b62e-e8c721d68915', 'Analfabetismo', NULL, 'Membros desta classe não sabem ler e escrever; Podem aprender caso adquiram um nível em qualquer outra classe.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('688e09d6-4712-4ac8-b66a-d7b7599e05a0', 'Fúria', NULL, '+2 nas jogadas de ataque e dano corpo-a-corpo; Redução de dano 1; Sofre –2 na classe de armadura; Não pode executar ações que exigem paciência ou concentração (como Furtividade ou magias); Usar é uma ação livre; Dura 5 + modificador de Constituição rodadas (pode terminar antes); Ao terminar, fica fatigado (Força –2, Destreza –2, não pode correr ou fazer investida) por um minuto; Pode entrar em fúria uma vez por encontro; 1 uso por dia (1º nível), +1 uso a cada 4 níveis seguintes (máximo 6 vezes por dia no 20º nível).', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('70e46831-c6e0-49ef-85ba-4c209594e295', 'Movimento Rápido', NULL, 'Seu deslocamento aumenta em +3m.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('686bca30-ce8e-4d87-a9cd-f79df912f7cc', 'Esquiva Sobrenatural', NULL, 'Nunca fica desprevenido; Se já tem esquiva sobrenatural de outra classe, recebe esquiva sobrenatural aprimorada.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('4910798e-8460-48f2-8c6a-f25981c2aae9', 'Instinto Selvagem', NULL, '+1 em testes de Iniciativa e Reflexos; Bônus aumenta em +1 a cada seis níveis seguintes.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('3fc8697b-a3f6-4b05-87ee-4c698f1519fa', 'Esquiva Sobrenatural Aprimorada', NULL, 'Não pode ser flanqueado.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('56ce7540-d931-4f52-bd6b-8e57e456a2f1', 'Redução de Dano', NULL, 'Redução de dano 1 (todo o dano de ataques físicos é reduzido em 1) a partir do 7º nível; A cada três níveis seguintes, sua RD aumenta em 1; Cumulativa com outras reduções de dano (incluindo a da fúria).', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('4a44127e-d57e-457c-916f-a88dfdd8de73', 'Fúria Maior', NULL, 'Bônus fornecido pela fúria nas jogadas de ataque e dano corpo-a-corpo aumenta para +3; Redução de dano da fúria aumenta para 3.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('ba6eca86-df01-49c6-b5b5-b0d2ff985fab', 'Vontade Inabalável', NULL, '+4 em testes de Vontade quando em fúria.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('2f6173e6-8778-4735-b1c7-2ef1b06826cb', 'Fúria Incansável', NULL, 'Não fica mais fatigado quando sua fúria termina.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('2af84dcb-7a94-416f-b606-945d8cf3169f', 'Fúria Poderosa', NULL, 'Bônus fornecido pela fúria nas jogadas de ataque e dano corpo-a-corpo aumenta para +4; Redução de dano da fúria aumenta para 5.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('461b6670-23a1-4ca9-903e-538a20a36b9e', 'Ex-Bárbaros', NULL, 'Um bárbaro que adota tendência Leal perde sua habilidade de Fúria e não pode mais ganhar níveis nesta classe; Mantém Redução de Dano, Movimento Rápido, Instinto Selvagem e Esquiva Sobrenatural.', 'Tormenta RPG', 0, NULL, 'decd064a-bde7-5b7b-b4c6-0058a3a2fec8');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('bb95eed9-bf0b-50d6-afb3-437de0c49a90', 'Bardo', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('12fc7c3d-3dcc-4a59-a0e6-631cf2273819', 'Conhecimento de Bardo', NULL, 'Pode fazer testes de qualquer perícia de Conhecimento como se fosse treinado nela; Recebe bônus igual a seu nível + modificador de Inteligência.', 'Tormenta RPG', 0, NULL, 'bb95eed9-bf0b-50d6-afb3-437de0c49a90');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('033edf2a-498c-476e-ba8a-8ada934b6076', 'Magias', NULL, 'Pode lançar magias arcanas e divinas; Lança magias de nível 0 e 1º nível; Lança magias de um nível acima a cada três níveis (até 6º nível no 16º); Habilidade-chave: Carisma; Conhece 4 magias de nível 0 e 1 + mod. Carisma de 1º nível; Aprende uma nova magia a cada nível; Possui 1 + mod. Carisma PM; Recebe 2 PM a cada nível; Não precisa preparar magias com antecedência; Pode lançar qualquer magia que conheça com PM suficientes.', 'Tormenta RPG', 0, NULL, 'bb95eed9-bf0b-50d6-afb3-437de0c49a90');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('50b968ec-096a-4d40-b5e7-c7259b61a095', 'Música de Bardo', NULL, 'Pode usar música (ou outra arte performática) para gerar efeitos mágicos; Começa com dois efeitos à sua escolha; Aprende um novo efeito no 2º nível e a cada dois níveis seguintes; Usar é uma ação padrão; Usos diários: nível + modificador de Carisma; Requer treinamento em Atuação; Afeta criaturas inteligentes (Int 3+) que podem ouvir/ver o bardo; Canção Assustadora: criatura faz teste de Vontade (CD 10 + metade do nível + mod. Carisma); falha: abalado; sucesso: imune por um dia; Canção Assustadora em Massa: como canção assustadora, mas afeta todas as criaturas escolhidas dentro do alcance (Pré-requisito: canção assustadora, 4º nível); Canção Apavorante: como canção assustadora, mas se a vítima falhar fica apavorada (Pré-requisito: canção assustadora, 4º nível); Fascinar: criatura faz teste de Vontade oposto por Atuação; sucesso: fascinada (não pode realizar ações, -4 Percepção) por até 1 minuto; falha: imune por um dia; ameaça óbvia cancela o efeito; Fascinar em Massa: como fascinar, mas afeta todas as criaturas escolhidas dentro do alcance (Pré-requisito: sugestão); Inspirar Competência: você e aliados recebem +2 em testes de perícia; Inspirar Competência Aprimorada: bônus de inspirar competência aumenta para +4 (Pré-requisito: inspirar competência, 4º nível); Inspirar Competência Maior: bônus de inspirar competência aumenta para +6 (Pré-requisito: inspirar competência aprimorada); Inspirar Coragem: você e aliados recebem +1 em jogadas de ataque, dano e testes de resistência contra medo; Inspirar Coragem Aprimorada: bônus de inspirar coragem aumenta para +2 (Pré-requisito: inspirar coragem, 4º nível); Inspirar Coragem Maior: bônus de inspirar coragem aumenta para +3 (Pré-requisito: inspirar coragem aprimorada); Inspirar Grandeza: você ou um aliado recebe 10 PV temporários e +2 em jogadas de ataque e testes de Fortitude (Pré-requisito: inspirar coragem aprimorada); Inspirar Heroísmo: você ou um aliado recebe +4 na CA e testes de resistência (Pré-requisito: inspirar coragem aprimorada); Melodia Libertadora: um aliado recebe o efeito da magia remover encantamento (Pré-requisito: melodia revigorante aprimorada); Melodia Revigorante: você e aliados curam 2d6 pontos de dano; Melodia Revigorante Aprimorada: você e aliados curam 4d6 pontos de dano (Pré-requisitos: melodia revigorante, 4º nível); Melodia Revigorante Maior: você e aliados curam 6d6 pontos de dano (Pré-requisito: melodia revigorante aprimorada); Sugestão: causa o efeito da magia sugestão a criatura fascinada; alvo tem teste de Vontade (CD 10 + metade do nível + mod. Carisma) para evitar; não conta como ameaça; pode tentar novamente (Pré-requisito: fascinar, 4º nível); Sugestão em Massa: como sugestão, mas afeta todas as criaturas escolhidas dentro do alcance (Pré-requisito: fascinar em massa).', 'Tormenta RPG', 0, NULL, 'bb95eed9-bf0b-50d6-afb3-437de0c49a90');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('b446a43c-9af7-55c8-9657-23bd9ac73c3c', 'Clérigo', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('1cd67594-53fc-401a-8670-2bdcb0780955', 'Devoto', NULL, 'Deve escolher uma divindade padroeira e atuar como seu devoto; Sua divindade determina quais talentos de poderes concedidos você pode ter.', 'Tormenta RPG', 0, NULL, 'b446a43c-9af7-55c8-9657-23bd9ac73c3c');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('0aed9e30-e567-48a0-a5e7-a3fe9a0c8131', 'Canalizar Energia Positiva/Negativa', NULL, 'Libera onda de energia positiva ou negativa (9m de alcance) conforme tendência; Bondosos canalizam positiva; Malignos canalizam negativa; Neutros escolhem no 1º nível (escolha permanente); Positiva: cura criaturas vivas ou causa dano a mortos-vivos (escolha no uso); Negativa: cura mortos-vivos ou causa dano a criaturas vivas (exceto você) (escolha no uso); Cura ou dano é 1d6 + 1d6 a cada dois níveis de clérigo; Criaturas que sofrem dano têm teste de Vontade (CD 10 + metade do nível + mod. Carisma) para reduzir à metade; Usar é uma ação padrão; Usos diários: 1 + modificador de Carisma.', 'Tormenta RPG', 0, NULL, 'b446a43c-9af7-55c8-9657-23bd9ac73c3c');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('d836566a-b296-4e72-9d15-9fc6f27902b6', 'Poder Divino', NULL, 'Recebe um talento adicional de magia ou de poder concedido; No 5º nível, e a cada cinco níveis seguintes, recebe outro talento de magia ou de poder concedido.', 'Tormenta RPG', 0, NULL, 'b446a43c-9af7-55c8-9657-23bd9ac73c3c');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('d91b6708-3b8d-4ee0-9bb0-e16980da1e86', 'Magias', NULL, 'Pode lançar magias divinas; Lança magias de nível 0 e 1º nível; Lança magias de um nível acima a cada dois níveis (até 9º nível no 17º); Habilidade-chave: Sabedoria; Conhece 4 magias divinas de nível 0 e 1 + mod. Sabedoria de 1º nível; Aprende duas novas magias a cada nível; Possui 1 + mod. Sabedoria PM; Recebe 3 PM a cada nível; Precisa preparar magias com antecedência; A cada dia, gasta uma hora rezando para sua divindade e gasta PM com magias que quer disponíveis.', 'Tormenta RPG', 0, NULL, 'b446a43c-9af7-55c8-9657-23bd9ac73c3c');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('3dcf6782-3e52-521f-b026-da7f35894f7b', 'Druida', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('a929dab6-1ba7-4004-bda0-7e6e8f9dfd2d', 'Código de Conduta', NULL, 'Não pode usar armaduras e escudos feitos de metal; Só pode usar armadura acolchoada, corselete de couro, gibão de peles e escudo leve (de madeira); Perde todas as habilidades de classe por um dia se usar armadura ou escudo de metal.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('3aa90ffb-fba4-4377-9a6a-1b3547e837aa', 'Devoto', NULL, 'Deve escolher uma divindade padroeira (Allihanna, Megalokk ou Oceano) e atuar como seu devoto; Sua divindade determina quais poderes concedidos você pode ter.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('330458cf-5a22-46c4-bc82-23810b98480a', 'Empatia Selvagem', NULL, 'Sabe se comunicar com animais (linguagem corporal e vocalizações); Pode fazer testes de Diplomacia com animais com um bônus igual a seu nível + modificador de Carisma.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('699bac2d-fd59-5558-b405-b7a2748c0bc1', 'Monge', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('31bab06e-dcd1-4bd3-8cd7-c581f688b9ff', 'Rajada de Golpes Aprimorada', NULL, '', 'Tormenta RPG', 0, NULL, '699bac2d-fd59-5558-b405-b7a2748c0bc1');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('4dfaa0c6-f70e-43b6-880e-df8910587841', 'Alma de Diamante', NULL, '', 'Tormenta RPG', 0, NULL, '699bac2d-fd59-5558-b405-b7a2748c0bc1');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('31ee3d3e-e369-416a-8280-2caa2c936f2e', 'Magias', NULL, 'Pode lançar magias divinas; Lança magias de nível 0 e 1º nível; Lança magias de um nível acima a cada dois níveis (até 9º nível no 17º); Habilidade-chave: Sabedoria; Conhece 4 magias divinas de nível 0 e 1 + mod. Sabedoria de 1º nível; Aprende duas novas magias a cada nível; Possui 1 + mod. Sabedoria PM; Recebe 3 PM a cada nível; Precisa preparar magias com antecedência; A cada dia, gasta uma hora rezando para sua divindade e gasta PM com magias que quer disponíveis.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('82d45abf-b404-481f-8556-3f79bc345d01', 'Vínculo Natural', NULL, 'Escolha permanente entre elo com forças da natureza ou com um animal; Elo com natureza: recebe um talento de magia ou poder concedido (no 1º, 5º e a cada cinco níveis seguintes); Elo com animal: recebe um companheiro animal.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('94406be1-9d48-45be-a47b-46f07458ad4a', 'Companheiro Animal', NULL, 'Aliado valoroso e leal do druida; Dar ordem exige ação de movimento; Ordens simples não exigem testes; Ordens complexas podem exigir teste de Adestrar Animais; Estatísticas iniciais (animal 1, N, Médio): desl. 9m; PV 7; CA 14 (+2 Des, +2 natural); corpo-a-corpo: mordida +2 (1d6+2); Fort +4, Ref +4, Von +1; For 15, Des 15, Con 15, Int 2, Sab 12, Car 6; Perícias & Talentos: Percepção +5; Vitalidade; Sobe de nível com o druida; Ganha BBA (+3/4 por nível) e PV (4 + mod. Con por nível) como um druida; Recebe benefícios da tabela “Benefícios por Nível do Personagem”; Cada animal possui uma habilidade da forma selvagem do druida; Recebe outra habilidade no 5º nível e a cada 5 níveis seguintes; A partir do 10º nível, pode escolher habilidades de forma selvagem aprimorada; A partir do 15º nível, pode escolher habilidades de forma selvagem maior; Não pode escolher a mesma habilidade duas vezes, nem a habilidade elemental; Se morto, o druida fica atordoado por 1d4 rodadas; Pode invocar um novo companheiro após passar um dia inteiro em uma região selvagem.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9622faa9-ebea-488c-b90e-c8ae85829fed', 'Caminho da Floresta', NULL, 'Pode atravessar terrenos difíceis sem redução no deslocamento; Só funciona em terrenos naturais.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('e23abbbc-7e7f-4c4b-804b-ac283d7bc680', 'Rastro Invisível', NULL, 'Pode atravessar terrenos naturais sem deixar marcas; Dificuldade para rastreá-lo aumenta em CD+10.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('71762747-b659-4ce1-b99c-89be710fe687', 'Forma Selvagem', NULL, 'Adquire forma de criatura selvagem (animal ou fera); Estatísticas não mudam, mas recebe uma habilidade da lista; Usar é uma ação padrão; Usos diários: 1 + modificador de Sabedoria; Não pode lançar magias na forma selvagem; Outras criaturas podem fazer teste de Percepção vs Enganação (+10) para perceber que não é um animal comum; Roupa/equipamento é absorvido e ressurge; Dura o tempo que quiser, reverte se ficar inconsciente ou morrer; No 8º nível, recebe duas habilidades diferentes; No 14º nível, três habilidades; No 20º nível, quatro habilidades; Pode escolher habilidades diferentes a cada transformação, mas nunca a mesma mais de uma vez; Habilidades Básicas: Agilidade (Destreza+4); Armadura natural (CA+4); Brutalidade (Força+4); Escalar (deslocamento 9m); Garras e Presas (dois ataques de garras 1d4, uma mordida 1d6, -4 em todos ataques se usar os três); Nadar (deslocamento 9m); Instintos Apurados (faro, visão na penumbra, +4 em Percepção); Rapidez (deslocamento +9m); Tamanho Grande (Força+4, -1 ataque/CA, -4 Furtividade); Tamanho Pequeno (+1 ataque/CA, +4 Furtividade).', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('645e3b96-a1f7-40cc-ab50-6901cd15ec45', 'Imunidade a Venenos', NULL, 'Imune a todos os venenos.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('880c0f7a-87de-4b05-b5e0-e1ae3526ae32', 'Forma Selvagem Aprimorada', NULL, 'Pode escolher habilidades adicionais de Forma Selvagem Aprimorada (a partir do 11º nível); Agarrar Instantâneo (acerta ataque corpo-a-corpo, inicia manobra de agarrar como ação livre); Agilidade (Destreza+8); Armadura natural (CA+6); Bote (faz investida, pode atacar com todas as armas naturais); Brutalidade (Força+8); Escalar (deslocamento 18m); Nadar (deslocamento 18m); Planta (corpo de matéria vegetal, CA+4, imunidade a veneno/sono/paralisia/atordoamento, dois ataques de pancada 1d6, -4 em ataques se usar os dois, +10 em Furtividade para esconder onde há vegetação); Rapidez (deslocamento +18m); Tamanho Enorme (Força+8, -2 ataque/CA, -8 Furtividade); Tamanho Mínimo (+2 ataque/CA, +8 Furtividade); Teia (lança teia em criatura a até 18m como ação padrão, ataque de toque à distância vs Reflexos, imobiliza, escapa com ação completa e teste de Força ou Acrobacia CD 25); Veneno (criatura atingida por ataque natural faz teste de Fortitude (CD 10 + metade do nível + mod. Constituição), falha: sofre +2d12 dano); Voar (deslocamento 9m).', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('a430d73e-9b34-424f-921d-60c66de38850', 'Mil Faces', NULL, 'Pode mudar sua aparência (como a magia alterar-se) como uma ação padrão.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('de073cd0-f10d-47b5-a638-04db0eadd028', 'Corpo Atemporal', NULL, 'Não sofre penalidades por envelhecimento; Imune a envelhecimento mágico; Bônus por envelhecimento ainda se aplicam; Morrerá de velhice normalmente.', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('ba8db5e2-a8f1-44f6-b22d-049041cdae94', 'Forma Selvagem Maior', NULL, 'Pode escolher habilidades adicionais de Forma Selvagem Maior (a partir do 17º nível); Armadura natural (CA+8); Atropelar (passa por criaturas duas ou mais categorias de tamanho menores, causa 4d6 + mod. Força de dano, Reflexos CD 10 + metade do nível + mod. Força para metade); Constrição (no início de cada rodada, causa automaticamente 1d8 + mod. Força de dano a criatura agarrando); Elemental (corpo feito de água, ar, fogo ou terra; RD 10/mágica, imunidade a atordoamento/paralisia/sono/veneno; dois ataques de pancada 1d6, -4 em ataques se usar os dois; não pode ser combinada com outras, exceto Agilidade/Brutalidade/Tamanhos); Água: nadar 18m, atravessar barreiras não hermeticamente fechadas; Ar: voar 18m; Fogo: imunidade a fogo, ataques naturais causam +1d6 dano por fogo; Terra: CA+4; Tamanho Descomunal (Força+16, -4 ataque/CA, -16 Furtividade); Tamanho Diminuto (+4 ataque/CA, +16 Furtividade); Voar (deslocamento 18m).', 'Tormenta RPG', 0, NULL, '3dcf6782-3e52-521f-b026-da7f35894f7b');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('cf02254a-9226-5c92-af9d-364e96381a1f', 'Mago', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('e79fb15f-91a0-4839-babd-786319fd1628', 'Vínculo Arcano', NULL, 'Item de Poder: se escolher um item, você recebe um objeto à sua escolha. Pode ser uma varinha, cajado, livro, chapéu, amuleto ou mesmo uma arma. Este item pode ser usado para lançar, uma vez por dia, qualquer magia que você conheça sem gastar PM (incluindo custos extras de talentos metamágicos). No entanto, para lançar qualquer magia sem estar usando ou segurando o item, você precisa fazer um teste de Identificar Magia (CD 15 + nível da magia). Se falhar, a magia não funciona, mas você gasta os PM mesmo assim. O item de poder tem redução de dano 10 e PV iguais a metade dos PV máximos do mago. Um item danificado é restaurado na próxima vez que você preparar suas magias. Se o item é destruído, você fica atordoado por 1d4 rodadas. Construir um novo item de poder consome uma semana de trabalho e 100 TO.\nFamiliar: se escolher um animal, você recebe um familiar — um tipo de animal de estimação mágico. Você e seu familiar podem se comunicar telepaticamente a até 1km. Seu familiar obedece suas ordens, mas sua baixa inteligência pode limitar o que ele consegue fazer. Se o familiar morre, você fica atordoado por 1d4 rodadas. Você pode invocar um novo familiar com um ritual que exige um dia inteiro e 100 TO em ingredientes. PVF amiliar. Animal 1, N; Mínimo, desl. 9m; PV (metade dos do mago); CA 14; corpo-a-corpo: mordida +4 (1); Fort +2, Ref +4, Von +1; For 4, Des 15, Con 10, Int 4, Sab 12, Car 6. Perícias & Talentos: Percepção +5; Acuidade com Arma. Cada tipo de animal oferece ainda uma habilidade especial: Cobra: você recebe Treino em Perícia (Enganação) ou Foco em Perícia (Enganação) como um talento adicional. Coruja: a coruja pode voar com deslocamento de 12m, e você recebe visão na penumbra. Corvo: o corvo pode voar com deslocamento de 12m, e você recebe Vontade de Ferro como um talento adicional. Falcão: o falcão pode voar com deslocamento de 12m, e você recebe Treino em Perícia (Percepção) ou Foco em Perícia (Percepção) como um talento adicional. Gato: você recebe Treino em Perícia (Furtividade) ou Foco em Perícia (Furtividade) como um talento adicional. Morcego: o morcego pode voar com deslocamento de 12m, e você recebe visão no escuro 18m. Rato: você recebe Fortitude Maior como um talento adicional. Sapo: você recebe Vitalidade como um talento adicional.', 'Tormenta RPG', 0, NULL, 'cf02254a-9226-5c92-af9d-364e96381a1f');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('63cb7387-5063-5c4b-87ad-43aec3fa41e0', 'Feiticeiro', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('7ce39fc3-8a53-43ff-8125-9450a32be9a4', 'Linhagem Sobrenatural', NULL, 'Linhagem Aberrante: seu olhar enervante desestabiliza outras criaturas. Todos os inimigos a até 9m sofrem –1 nas jogadas e testes. No 5º nível, seus órgãos vitais mudam de maneira bizarra. Você recebe 25% de chance de ignorar acertos críticos realizados contra você. No 10º nível, seus membros se esticam. Seu deslocamento aumenta em 3m e seu alcance natural aumenta em 1,5m. No 15º nível, você passa a perceber o mundo de maneira diferente. Você recebe percepção às cegas 18m. No 20º nível, seu corpo se torna ainda mais alienígena. Você se torna imune a acertos críticos e recebe redução de dano 5.\nLinhagem Dracônica: você recebe dois ataques naturais de garras, que causam dano equivalente a uma adaga própria para seu tamanho (1d4 para uma criatura Média). Você pode atacar com as duas garras na mesma rodada, mas se fizer isso sofre uma penalidade de –4 nas jogadas de ataque. No 5º nível, pequenas escamas surgem em seu corpo. Você recebe CA +2. No 10º nível, você recebe um ataque de sopro, que causa 1d6 pontos de dano de por nível. Quando recebe esta habilidade, deve escolher o tipo de dano do sopro: ácido, eletricidade, fogo ou frio. O sopro afeta um cone de 9m. As criaturas na área podem fazer um teste de Reflexos (CD 10 + metade do seu nível + modificador de Carisma) para reduzir o dano à metade. Usar o sopro é uma ação padrão, e ele pode ser usado uma vez por dia. A partir do 15º nível, com uma ação de movimento, você pode fazer surgir grandes asas de couro em suas costas, e voar com deslocamento de 18m. A partir do 20º nível, com uma ação padrão, você pode se transformar em um dragão. Você se torna uma criatura Enorme, recebe Força+16, CA+8, dois ataques naturais com garras (2d6 de dano) e um ataque natural de mordida (2d8 de dano). Você pode atacar com as duas garras e a mordida, mas se fizer isso sofre uma penalidade de –4 nas jogadas de ataque.\nLinhagem Elemental: escolha entre água, ar, fogo ou terra. Cada elemento é ligado a um ou mais descritores: água — água e frio; ar — ar e eletricidade; fogo — fogo; terra — terra e ácido. Você recebe 1 PM extra, que pode usar apenas para magias de descritores ligados a seu elemento. No 5º nível, você recebe resistência 10 contra os descritores ligados ao seu elemento. No 10º nível, a dificuldade contra as magias dos descritores ligados ao seu elemento aumenta em CD +1. No 15º nível, você recebe uma habilidade de acordo com seu elemento. Água: deslocamento de natação de 18m e pode atravessar qualquer barreira que não seja hermeticamente fechada. Ar: deslocamento de voo de 18m. Fogo: suas magias de fogo causam +1 de dano por dado. Terra: redução de dano 5. No 20º nível, você transcende sua forma física e se torna elemental. Você se torna imune a atordoamento, doença, paralisia, sono, veneno e aos descritores ligados ao seu elemento.', 'Tormenta RPG', 0, NULL, '63cb7387-5063-5c4b-87ad-43aec3fa41e0');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('a8c5672b-f2bf-4653-b03b-c4783f877347', 'Magias', NULL, 'Tipo e níveis de magia: você pode lançar magias arcanas de nível 0 (truques) e 1º nível. A cada dois níveis de feiticeiro seguintes, você pode lançar magias de um nível acima: no 3º nível você pode lançar magias de 2º nível, no 5º nível você pode lançar magias de 3º nível e assim por diante, até o 17º nível, quando você pode lançar magias de 9º nível.\nHabilidade-chave: sua habilidade para lançar magias é Carisma.\nMagias Conhecidas: você conhece 4 magias arcanas de nível 0, e também um número de magias de 1º nível igual a 1 + seu modificador de Carisma. Cada vez que avança de nível, você aprende uma nova magia de qualquer nível que possa lançar.\nPontos de Magia: você tem um número de pontos de magia (PM) igual a 3 + seu modificador de Carisma. Cada vez que você avança de nível, recebe 3 PM.\nPreparação de Magia: você não precisa preparar suas magias com antecedência. Você pode lançar qualquer magia que conheça, se tiver PM suficientes.', 'Tormenta RPG', 0, NULL, '63cb7387-5063-5c4b-87ad-43aec3fa41e0');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('21cc2cc9-23f1-5733-80a5-1a44576d5254', 'Guerreiro', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('96a22de5-5619-4448-b90d-2216bc172798', 'Técnica de Luta', NULL, '', 'Tormenta RPG', 0, NULL, '21cc2cc9-23f1-5733-80a5-1a44576d5254');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b', 'Ladino', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
