INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('eed039b1-d36b-4adf-a738-0a0eaa0cd808', 'Encontrar Armadilhas', NULL, '', 'Tormenta RPG', 0, NULL, 'cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('28ef76bb-3216-450e-9b12-8e5e0d2a8cf2', 'Evasão', NULL, '', 'Tormenta RPG', 0, NULL, 'cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('cb7d05fe-fa76-4ef1-9e32-1f9d8fce3eb4', 'Técnica Ladina', NULL, 'Ataque Incapacitante: quando atinge uma criatura com um ataque furtivo, além de sofrer dano extra, ela sofre uma penalidade de –2 em jogadas e testes por um minuto.\nDe Pé: você pode se levantar com uma ação livre, em vez de uma ação de movimento.\nDesabilitar Rápido: você gasta uma ação padrão para desabilitar mecanismos, em vez de 1d4 rodadas (veja a perícia Ladinagem).\nFurtividade Rápida: você pode usar Furtividade mesmo se movendo com seu deslocamento normal, sem sofrer penalidades no teste de perícia.\nMaestria em Perícia: escolha um número de perícias treinadas igual a 1 + seu modificador de Inteligência. Usando essas perícias, você pode escolher 10 mesmo quando distraído ou sob pressão.\nMente Escorregadia: sempre que faz um teste de Vontade e falha, você pode repetir o teste uma vez na rodada seguinte.\nOportunismo: você recebe +4 em jogadas de ataque contra inimigos que já sofreram dano na mesma rodada.\nRolamento Defensivo: quando você sofre dano, pode fazer um teste de Reflexos (CD = dano sofrido). Se for bem-sucedido, sofre apenas metade do dano. Você pode usar esta técnica ladina apenas uma vez por dia (mas pode escolhê-la mais vezes, para mais utilizações diárias).\nTruque de Combate: você recebe um talento de combate adicional. Você pode escolher esta habilidade diversas vezes.\nTruque de Perícia: você recebe um talento de perícia adicional. Você pode escolher esta habilidade diversas vezes.\nTruque Mágico: você pode lançar uma magia arcana de 1º nível à sua escolha. Sua habilidade-chave é Inteligência, e você possui um número de pontos de magia igual a 1 + seu modificador de Inteligência. Você pode escolher esta habilidade diversas vezes. Cada vez que é escolhida, você aprende uma nova magia e recebe +1 PM.', 'Tormenta RPG', 0, NULL, 'cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('0e38f6af-dba8-4ff6-98bc-ebe9462d7c3e', 'Sentir Armadilhas', NULL, '', 'Tormenta RPG', 0, NULL, 'cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('83de3cc4-cc9d-49ea-b337-a1cac0b5a123', 'Esquiva Sobrenatural', NULL, '', 'Tormenta RPG', 0, NULL, 'cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b');
