INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('f41df859-0421-4183-8060-097135dac7da', 'Evasão Aprimorada', NULL, '', 'Tormenta RPG', 0, NULL, 'cb9a79c5-dda7-5b7d-8aff-be9d0b95c13b');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('fe4b7568-ad96-4179-a72e-aecf29e30aab', 'Magias', NULL, 'Tipo e níveis de magia: você pode lançar magias arcanas de nível 0 (truques) e 1º nível. A cada dois níveis de mago seguintes, você pode lançar magias de um nível acima: no 3º nível pode lançar magias de 2º nível, no 5º nível pode lançar magias de 3º nível e assim por diante, até o 17º nível, quando você pode lançar magias de 9º nível.\nHabilidade-chave: sua habilidade para lançar magias é Inteligência.\nMagias Conhecidas: você conhece cinco magias arcanas de nível 0, e também um número de magias de 1º nível igual a 3 + seu modificador de Inteligência. Cada vez que avança de nível, você aprende duas novas magias de qualquer nível que possa lançar.\nPontos de Magia: você tem um número de pontos de magia (PM) igual a 1 + seu modificador de Inteligência. Cada vez que você avança de nível, recebe 3 PM.\nPreparação de Magia: você precisa preparar suas magias com antecedência. A cada dia deve estudar durante uma hora, e então gastar seus PM com as magias que vai querer disponíveis durante o dia.', 'Tormenta RPG', 0, NULL, 'cf02254a-9226-5c92-af9d-364e96381a1f');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('46917a98-18f8-4479-a630-17b2af566275', 'Mistérios Arcanos', NULL, '', 'Tormenta RPG', 0, NULL, 'cf02254a-9226-5c92-af9d-364e96381a1f');
