INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('b48e0967-709b-4062-a586-372505d96849', 'Corpo Vazio', NULL, '', 'Tormenta RPG', 0, NULL, '699bac2d-fd59-5558-b405-b7a2748c0bc1');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9c91f991-e122-43cb-91a1-c895913744fd', 'Autoperfeição', NULL, '', 'Tormenta RPG', 0, NULL, '699bac2d-fd59-5558-b405-b7a2748c0bc1');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('38ef753a-5102-5821-9352-cf94670eb361', 'Paladino', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('52d0544c-33b3-4fb6-a1e0-f9bb2c7bbe44', 'Código de Conduta', NULL, 'Não aceita aliados de tendência Maligna; Perde todas as habilidades de classe se executar ato maligno até realizar penitência.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('6ba7f3cd-d16a-480f-a81d-0a420f327d8f', 'Devoto', NULL, 'Escolhe divindade padroeira (Allihanna, Azgher, Khalmyr, Lena, Lin-Wu, Marah, Tanna-Toh, Tauron, ftyatis, Valkaria); Atua como devoto; Divindade determina poderes concedidos.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('65a058c3-9268-4e1d-bc14-1c68cf1b8997', 'Destruir o Mal', NULL, 'Ação livre antes de ataque corpo-a-corpo; Contra alvo Maligno: soma bônus de Carisma à jogada de ataque e nível de paladino ao dano; Gasta uso mesmo contra alvo não Maligno; Usos diários: 1/dia base, +1 a cada 3 níveis.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('6c1b9184-102e-400a-b24b-11ed5d729bbf', 'Detectar o Mal', NULL, 'Lança a magia detectar o mal à vontade, sem gastar PM.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('16cb7043-03f0-4b0a-b14c-3641659bdeed', 'Cura pelas Mãos', NULL, 'No 2º nível, cura 1d8+1 PV com toque (ação padrão); Aumenta 1d8+1 no 6º nível e a cada 4 níveis seguintes; Causa dano a mortos-vivos (ataque desarmado); Usos diários: 1 + modificador de Carisma.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('b8c705b3-5fb2-4895-a1d8-135e2abf33cf', 'Graça Divina', NULL, 'No 2º nível, soma bônus de Carisma a todos os testes de resistência.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('c05df952-4545-4b29-9edc-4e34aab7df9d', 'Aura de Coragem', NULL, 'No 3º nível, imune a medo; Aliados a até 3m recebem +4 em testes de resistência contra medo.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('b3e9a019-43e2-4866-8be7-a7812ea0844d', 'Saúde Divina', NULL, 'No 3º nível, imune a doenças mundanas (ainda afetado por doenças mágicas ou maldições).', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9267c71e-7946-4a3c-a378-2d456859a95d', 'Canalizar Energia Positiva', NULL, 'A partir do 4º nível, emana energia positiva em 9m (ação padrão); Cura criaturas vivas ou causa dano a mortos-vivos; Dano/cura: 1d6, +1d6 a cada 4 níveis seguintes; Teste de Vontade (CD 10 + metade do nível + mod. Carisma) para reduzir dano à metade; Usos diários: 1 + modificador de Carisma.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('785e4d34-4c88-4b08-a3ab-398408c53a3e', 'Bênção da Justiça', NULL, 'Escolhe Magias ou Poderes de Paladino no 5º nível (escolha permanente).\nSe escolher Magias:\n  - Lança magias divinas (1º nível no 5º, +1 nível a cada 4 níveis seguintes: 9º: 2º, 13º: 3º, 17º: 4º);\n  - Habilidade-chave: Sabedoria; Magias Conhecidas: 1 + mod. Sabedoria, +1 por nível de paladino; Pontos de Magia: 1 + mod. Sabedoria, +1 por nível de paladino; Prepara magias diariamente rezando por 1 hora.\nSe escolher Poderes de Paladino:\n  - Arma da Fé (5º nível): ataques corpo-a-corpo são armas mágicas e Bondosas;\n  - Armadura da Fé (9º nível): CA+2;\n  - Poder Sagrado (13º nível): +4 em ataque e dano por 1 minuto (ação padrão, 1/dia);\n  - Campeão do Bem (17º nível): Redução de dano 20 por 1 minuto (ação padrão, 1/dia).', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5c512ff2-09d1-44c2-bc71-09a355aa1340', 'Vínculo Divino', NULL, 'No 5º nível, escolhe Elo com Forças Divinas ou Elo com Animal (escolha permanente).\nSe escolher Elo com Forças Divinas:\n  - Recebe um talento de combate ou poder concedido;\n  - Recebe outro talento de combate ou poder concedido no 10º nível e a cada 5 níveis seguintes.\nSe escolher Elo com Animal:\n  - Recebe uma montaria sagrada.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('29d31e71-d634-4e14-b3a9-bda4d015d8de', 'Remover Condição', NULL, 'No 6º nível, com Cura pelas Mãos, remove 1 condição da lista (abalado, apavorado, atordoado, cego, doente, exausto, fatigado, surdo); Apavorado vira abalado, exausto vira fatigado; Escolhe outra condição no 9º nível e a cada 3 níveis seguintes; Cura apenas uma condição por uso de Cura pelas Mãos.', 'Tormenta RPG', 0, NULL, '38ef753a-5102-5821-9352-cf94670eb361');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('33025583-d17c-5406-9d30-0c4c2b8a736d', 'Ranger', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5c3b9baa-6eac-45ec-b602-6516c4196cdb', 'Empatia Selvagem', NULL, 'Comunica com animais; Testes de Diplomacia com animais com bônus = nível + mod. Carisma.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5bee9ace-e996-4059-9977-5dbd9d400396', 'Inimigo Predileto', NULL, 'Escolhe 1 tipo de criatura (animal, construto, espírito, humanoide, monstro, morto-vivo); +2 nas jogadas de dano e testes de Percepção, Intuição, Sobrevivência contra o tipo escolhido; Escolhe outro tipo e/ou aumenta bônus em +2 no 5º nível e a cada 5 níveis seguintes.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('b52dd417-5194-4da3-abd1-26856b592840', 'Estilo de Combate', NULL, 'No 2º nível, escolhe arquearia (recebe Tiro Rápido) ou luta com duas armas (recebe Combater com Duas Armas).', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('a787fcc9-0130-44db-a2df-21d10a8c981f', 'Terreno Predileto', NULL, 'No 3º nível, escolhe 1 tipo de terreno; +2 na CA e testes de Acrobacia, Atletismo, Furtividade, Percepção, Sobrevivência no terreno escolhido; Escolhe outro terreno e/ou aumenta bônus em +2 no 8º nível e a cada 5 níveis seguintes.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('81b40b4d-3d7a-4915-8061-6eb675f92790', 'Tolerância', NULL, 'No 3º nível, recebe Tolerância como talento adicional.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('6f3df5ed-ee65-4539-9679-94c1095a6c1f', 'Vínculo Selvagem', NULL, 'No 4º nível, escolhe Elo com Mundo Selvagem ou Elo com Animal (escolha permanente).\nSe escolher Elo com Mundo Selvagem:\n  - Recebe talento de combate ou perícia;\n  - Recebe outro talento de combate ou perícia no 9º nível e a cada 5 níveis seguintes.\nSe escolher Elo com Animal:\n  - Recebe um companheiro animal (como druida 3 níveis abaixo).', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('b0c55356-5198-4212-9835-10dd2f9f7df4', 'Bênção da Natureza', NULL, 'No 5º nível, escolhe Magias ou Técnicas de Ranger (escolha permanente).\nSe escolher Magias:\n  - Lança magias divinas (1º nível no 5º, +1 nível a cada 4 níveis seguintes: 9º: 2º, 13º: 3º, 17º: 4º);\n  - Habilidade-chave: Sabedoria; Magias Conhecidas: 1 + mod. Sabedoria, +1 por nível de ranger; Pontos de Magia: 1 + mod. Sabedoria, +1 por nível de ranger; Prepara magias diariamente orando por 1 hora.\nSe escolher Técnicas de Ranger:\n  - Movimento Rápido (5º nível): deslocamento aumenta em +3m;\n  - Armadilhas (9º nível): prepara armadilhas (10 min, max 1 + mod. Sabedoria/dia); Área de 3m; CD para encontrar 20 + mod. Sab; Teste de Reflexos (CD 20 + mod. Sab) para evitar 6d6 dano ou imobilização (escape CD 30);\n  - Ervas Curativas (13º nível): cura 4d8+4 PV e remove veneno (ação padrão, 1/dia);\n  - Olho do Caçador (17º nível): ação de movimento para analisar criatura em 9m; +4 nas jogadas de ataque e margem de ameaça dobrada contra essa criatura por 1 dia.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5fa0fcc8-046e-407a-ae5d-d5e74c9c55e2', 'Estilo de Combate Aprimorado', NULL, 'No 6º nível, se arquearia: recebe Tiro Múltiplo; se luta com duas armas: recebe Combater com Duas Armas Aprimorado.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5eae8fd3-aa30-4a28-8c8f-9dfd2fdc49f4', 'Caminho da Floresta', NULL, 'No 7º nível, atravessa terrenos difíceis em terrenos naturais sem redução de deslocamento.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9c57b5e4-e028-4889-bfbd-03ef3afd3281', 'Rastreador Eficaz', NULL, 'No 8º nível, move com deslocamento normal rastreando, sem penalidades em teste de Sobrevivência.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('624f2858-87a4-4a9a-8dcd-4616c23378ca', 'Evasão', NULL, 'No 9º nível, sucesso em teste de Reflexos contra dano pela metade resulta em nenhum dano; Falha resulta em dano normal; Exige liberdade de movimentos (sem imobilização, escudo, armadura média/pesada).', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('230a1fc1-fa2b-41e1-be79-81334d45aea8', 'Domínio do Estilo de Combate', NULL, 'No 11º nível, se arquearia: recebe Tiro Preciso Aprimorado; se luta com duas armas: recebe Combater com Duas Armas Maior.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9a13c08b-aca0-4027-8d40-929a4ae2ddd9', 'Rastro Invisível', NULL, 'No 12º nível, atravessa terrenos naturais sem deixar rastros; Dificuldade para rastrear aumenta em CD+10.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('f6b681fd-a7d9-4329-851f-da1205179932', 'Camuflagem', NULL, 'No 13º nível, usa Furtividade para se esconder mesmo sem cobertura disponível.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5fa338f0-6d11-48f2-861e-e955bd402b88', 'Mimetismo', NULL, 'No 17º nível, usa Furtividade para se esconder mesmo sob observação.', 'Tormenta RPG', 0, NULL, '33025583-d17c-5406-9d30-0c4c2b8a736d');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('353f4a4d-bc5a-5246-9251-2f23dcc55fcb', 'Samurai', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('e3fc92eb-d89c-491e-b46e-feea23bf6bc9', 'Espadas Ancestrais', NULL, 'No 1º nível, recebe katana e wakizashi (daisho) sem custo; No 1º nível e a cada 2 níveis seguintes, 1 arma do daisho recebe +1 bônus mágico (melhoria ou habilidades mágicas); Armas comuns para outros; Perda/Destruição de arma causa -1 em jogadas/testes até substituição; Katana exige 2 mãos até adquirir Usar Arma Exótica (katana); Opção de escolher outra arma obra-prima como arma ancestral.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('53d77917-e06c-438f-8812-ecb1cb173562', 'Estilo de Combate', NULL, 'No 2º nível, escolhe iaijutsu (recebe Saque Rápido) ou luta com duas armas (recebe Combater com Duas Armas).', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9946d0b7-1454-4503-8fc0-aabb0851ef7b', 'Grito de Kiai', NULL, 'No 2º nível, ação livre: +2 nas jogadas de ataque e dano por 1 rodada; Usos diários: 1 + modificador de Sabedoria.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('ba1b8d67-e8a9-401e-8d17-a55febaeb6ab', 'Técnica de Luta', NULL, 'No 4º nível, recebe talento de combate adicional; Recebe outro talento de combate no 8º nível e a cada 4 níveis seguintes.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('06df2585-99d0-4306-8954-103ed9ba1ade', 'Estilo de Combate Aprimorado', NULL, 'No 6º nível, se iaijutsu: recebe Foco em Perícia (Iniciativa); se luta com duas armas: recebe Combater com Duas Armas Aprimorado.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('5b16dd95-23de-4f63-94ac-d3e01bf4e84f', 'Olhar Assustador', NULL, 'No 7º nível, ação de movimento: assusta criatura em 9m (teste de Intimidar vs. Vontade); Sucesso: criatura abalada por 1 minuto; Falha: criatura imune por 1 dia.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('4d7d6587-f177-43a0-9cd9-07db87102f04', 'Grito de Kiai Aprimorado', NULL, 'No 10º nível, bônus do Grito de Kiai aumenta para +4 em jogadas de ataque e dano.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('96079fce-d821-402c-b50b-2e28c3d02506', 'Domínio do Estilo de Combate', NULL, 'No 11º nível, se iaijutsu: recebe Iniciativa Aprimorada; se luta com duas armas: recebe Combater com Duas Armas Maior.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('61f6f37d-e6de-4435-96fe-490e7edf892f', 'Olhar Assustador em Massa', NULL, 'No 14º nível, Olhar Assustador afeta todas as criaturas escolhidas dentro do alcance.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('9cde443f-7b20-4b25-ac4b-de525b20f11e', 'Grito de Kiai Maior', NULL, 'No 18º nível, bônus do Grito de Kiai aumenta para +6 em jogadas de ataque e dano.', 'Tormenta RPG', 0, NULL, '353f4a4d-bc5a-5246-9251-2f23dcc55fcb');
INSERT INTO public.player_class (id, name, resume, description, book, page, type) VALUES ('6961f702-1def-5910-800a-435d01425e05', 'Swashbuckler', 'Classe Base do Tormenta RPG', 'Descrição da classe disponível no livro.', 'Tormenta RPG', 0, 'base_class') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('34e92f11-ffb8-4d78-a600-0a9f007c0bfd', 'Autoconfiança', NULL, 'Soma bônus de Carisma à CA; Recebe CA+1 no 5º nível e a cada 5 níveis seguintes; Nota: Exige liberdade de movimentos (sem imobilização, armadura ou escudo).', 'Tormenta RPG', 0, NULL, '6961f702-1def-5910-800a-435d01425e05');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('2940544c-1824-4e46-bdcc-7c5be3c29eac', 'Técnica de Luta', NULL, 'Recebe um talento de combate; Recebe outro talento de combate no 2º nível e a cada 4 níveis seguintes.', 'Tormenta RPG', 0, NULL, '6961f702-1def-5910-800a-435d01425e05');
INSERT INTO public.class_abilities (id, name, resume, description, book, page, type, player_class_id) VALUES ('86dfe492-26d4-4bdc-984c-47807265388f', 'Estilo de Combate', NULL, 'No 2º nível, escolhe esgrima (recebe Acuidade com Arma) ou tiro (recebe Usar Arma Exótica (pistola ou mosquete)).', 'Tormenta RPG', 0, NULL, '6961f702-1def-5910-800a-435d01425e05');
